INSERT INTO public.sermon_templates (title, theme, key_verse, sermon_type, tags, content)
SELECT v.title, v.theme, v.key_verse, v.sermon_type, v.tags, v.content
FROM (
  VALUES
  (
    'A Paz que Excede Todo Entendimento',
    'Vencendo a Ansiedade pela Oração e Gratidão',
    'Filipenses 4:6-7',
    'Expositivo',
    ARRAY['Ansiedade', 'Paz', 'Oração', 'Fé', 'Consolo']::TEXT[],
    '{"introduction":"Em um mundo tomado por incertezas e sobrecarga mental, o apóstolo Paulo, mesmo preso em Roma, nos apresenta o antídoto de Deus para a inquietação da alma.","blocks":[{"id":"b1","title":"1. O Mandamento Divino: Não Andeis Ansiosos","biblicalReference":"Filipenses 4:6a","explanation":"O verbo grego merimnao denota uma mente dividida, despedaçada em direções opostas. Deus não nos proíbe de sentir aflições, mas de sermos governados pelo medo do amanhã.","illustration":"Como uma corda que arrebenta sob tensão contínua, o ser humano adoece quando insiste em carregar os fardos do futuro hoje.","application":"Entregue nas mãos do Pai tudo aquilo que você não pode controlar com suas próprias forças.","orderIndex":0},{"id":"b2","title":"2. O Método Bíblico: Oração com Gratidão Antecipada","biblicalReference":"Filipenses 4:6b","explanation":"As petições devem ser apresentadas com ações de graças (eucharistia). A gratidão ativa a memória da fidelidade de Deus no passado e alimenta a fé no presente.","illustration":"O pássaro que canta na escuridão da madrugada porque sabe com certeza matemática que o sol nascerá.","application":"Antes de apresentar a lista de pedidos a Deus, passe cinco minutos agradecendo pelos livramentos que Ele já operou.","orderIndex":1},{"id":"b3","title":"3. O Resultado Sobrenatural: A Paz Sentinela","biblicalReference":"Filipenses 4:7","explanation":"A paz de Deus age como uma sentinela militar (phroureo), guardando a mente e os sentimentos contra os dardos inflamados do inimigo.","illustration":"Enquanto tempestades assolam a superfície marítima, a 200 metros de profundidade as águas permanecem em calmaria inabalável.","application":"Deixe o Espírito Santo ser a sentinela que decide quais pensamentos têm permissão para habitar o seu coração.","orderIndex":2}],"conclusion":"A paz de Deus não depende da ausência de tempestades na vida exterior, mas da presença inegociável do Príncipe da Paz habitando o nosso interior.","appeal":"Convido você que está com o coração aflito a entregar todo o seu fardo a Jesus nesta hora."}'::jsonb
  ),
  (
    'O Bom Pastor e a Suficiência Divina',
    'O Cuidado Perfeito de Deus em Todas as Estações da Vida',
    'Salmo 23:1-6',
    'Expositivo',
    ARRAY['Provisão', 'Cuidado', 'Proteção', 'Salmos', 'Descanso']::TEXT[],
    '{"introduction":"Davi não escreveu o Salmo 23 em um palácio de mármore como rei soberano, mas a partir de sua rica memória de pastor nos desertos da Judeia.","blocks":[{"id":"b4","title":"1. A Suficiência Plena: Nada Me Faltará","biblicalReference":"Salmo 23:1-3","explanation":"Jeová Rohi (O Senhor é meu Pastor). A ovelha não planeja o pasto; ela simplesmente confia na sabedoria daquele que a conduz.","illustration":"Uma ovelha deitada ao meio-dia demonstra saciedade absoluta e ausência total de medo de predadores.","application":"Descanse na fidelidade de Deus e renuncie à obsessão pelo controle.","orderIndex":0},{"id":"b5","title":"2. A Companhia no Vale da Sombra da Morte","biblicalReference":"Salmo 23:4","explanation":"No vale, Davi muda o pronome: de Ele (terceira pessoa) para Tu (segunda pessoa). O sofrimento transforma a teologia teórica em intimidade face a face.","illustration":"A vara afasta os lobos e o cajado resgata a ovelha do abismo. Ambos trazem consolo.","application":"Lembre-se: o vale é apenas um lugar de passagem, nunca o seu destino final.","orderIndex":1},{"id":"b6","title":"3. A Mesa no Meio dos Adversários e a Unção de Honra","biblicalReference":"Salmo 23:5-6","explanation":"Deus não espera os inimigos desaparecerem para nos honrar e saciar; Ele prepara o banquete na presença deles.","illustration":"O azeite derramado sobre a cabeça da ovelha impedia que pragas e moscas ferissem seus olhos e ouvidos.","application":"Receba a unção do Espírito Santo que neutraliza os venenos da difamação e da afronta.","orderIndex":2}],"conclusion":"Bondade e misericórdia não são hipóteses; são as duas sentinelas divinas que seguem o crente até a eternidade.","appeal":"Renda hoje a liderança da sua vida àquele que deu a própria vida pelas Suas ovelhas."}'::jsonb
  ),
  (
    'Mais que Vencedores em Cristo',
    'A Segurança Eterna e Inabalável do Amor de Deus',
    'Romanos 8:31-39',
    'Expositivo',
    ARRAY['Vitória', 'Amor de Deus', 'Segurança', 'Esperança']::TEXT[],
    '{"introduction":"Paulo encerra o maior capítulo teológico do Novo Testamento com um hino triunfal de certeza inegociável na salvação.","blocks":[{"id":"b7","title":"1. A Lógica Insuperável da Graça","biblicalReference":"Romanos 8:31-32","explanation":"Se Deus não poupou o Seu próprio Filho, como deixará de nos conceder as menores necessidades de nossa caminhada?","illustration":"Quem doa um diamante raro de sua coleção não negará a caixa de veludo para protegê-lo.","application":"Nunca duvide do cuidado do Pai para as necessidades terrenas se Ele já resolveu sua eternidade.","orderIndex":0},{"id":"b8","title":"2. A Impossibilidade de Acusação Contra os Eleitos","biblicalReference":"Romanos 8:33-34","explanation":"O Juiz supremo é quem justifica; o Filho glorificado está à destra intercedendo ininterruptamente.","illustration":"O tribunal mais alto do universo já bateu o martelo declarando: ''Sem condenação!''.","application":"Rejeite as vozes da culpa e da acusação com base no sangue de Jesus.","orderIndex":1},{"id":"b9","title":"3. O Amor do Qual Nenhuma Criatura Pode Nos Separar","biblicalReference":"Romanos 8:35-39","explanation":"Hupermikao (supervencedores). Não somos imunes à tribulação, mas triunfamos no meio dela pelo amor de Cristo.","illustration":"A âncora fincada na rocha submersa sustenta o navio nas maiores tempestades marítimas.","application":"Tenha a convicção inabalável de que nem a morte nem o inferno podem quebrar o laço do amor de Deus por você.","orderIndex":2}],"conclusion":"Em Cristo, a vitória final não é uma probabilidade, é um fato consumado na cruz do Calvário.","appeal":"Celebre o amor de Deus e viva com a cabeça erguida diante das lutas desta semana."}'::jsonb
  ),
  (
    'A Armadura de Deus para os Dias Maus',
    'Firmeza Espiritual e Vitória no Poder do Senhor',
    'Efésios 6:10-18',
    'Expositivo',
    ARRAY['Batalha Espiritual', 'Firmeza', 'Oração', 'Vitória']::TEXT[],
    '{"introduction":"A vida cristã não é um piquenique de lazer, mas um campo de batalha espiritual. Paulo nos ensina a lutar com as armas certas.","blocks":[{"id":"b10","title":"1. O Fortalecimento no Senhor e na Força do Seu Poder","biblicalReference":"Efésios 6:10-11","explanation":"Nossa força humana é insuficiente contra os principados e potestades. A ordem é ficar firmes na força dele.","illustration":"O soldado romano com sandálias cravadas de pregos para manter a base firme no combate corpo a corpo.","application":"Não enfrente as lutas diárias confiando na sua própria esperteza ou recursos humanos.","orderIndex":0},{"id":"b11","title":"2. As Armas de Defesa: Verdade, Justiça, Fé e Salvação","biblicalReference":"Efésios 6:14-17a","explanation":"O cinturão da verdade sustenta todas as outras peças. O escudo da fé apaga todos os dardos inflamados do maligno.","illustration":"Os escudos romanos cobertos de couro molhado para apagar flechas em chamas disparadas de longe.","application":"Alimente a fé com as promessas da Palavra para apagar as setas da dúvida e do desânimo.","orderIndex":1},{"id":"b12","title":"3. A Espada do Espírito e a Oração em Todo o Tempo","biblicalReference":"Efésios 6:17b-18","explanation":"A Palavra de Deus (rhema) é a única arma de ataque. A oração no Espírito é o oxigênio que mantém o soldado ativo.","illustration":"Jesus respondeu a Satanás no deserto repetindo: ''Está escrito!''.","application":"Memorize e declare a Palavra de Deus sobre suas crises financeiras, familiares e emocionais.","orderIndex":2}],"conclusion":"Quem veste a armadura de Deus permanece de pé mesmo depois que a poeira dos dias maus baixar.","appeal":"Levante-se, vista a armadura e tome a sua posição de vitória em Cristo."}'::jsonb
  ),
  (
    'A Maturidade Forjada na Provação',
    'Transformando o Sofrimento em Perseverança e Sabedoria',
    'Tiago 1:2-12',
    'Expositivo',
    ARRAY['Provação', 'Maturidade', 'Sabedoria', 'Fé']::TEXT[],
    '{"introduction":"Tiago não diz ''se'' passardes por provações, mas ''quando'' passardes. As provações são o laboratório divino de maturidade.","blocks":[{"id":"b13","title":"1. A Alegria Paradoxal no Crisol da Fé","biblicalReference":"Tiago 1:2-4","explanation":"Considerar com alegria não é masoquismo, mas foco no fruto final que o teste produzirá: paciência e integridade.","illustration":"O atleta que celebra o cansaço do treino intenso porque sabe que ele forja o músculo para a vitória.","application":"Mude sua pergunta de ''Por que eu, Senhor?'' para ''O que o Senhor quer me ensinar com isso?''.","orderIndex":0},{"id":"b14","title":"2. A Busca por Sabedoria sem Vacilação","biblicalReference":"Tiago 1:5-8","explanation":"Deus concede sabedoria generosamente a quem pede com fé. A mente dividida é instável como a onda do mar revolto.","illustration":"Um barco sem leme levado pelo sopro de qualquer vento contra os recifes pontiagudos.","application":"Busque a direção de Deus de joelhos antes de tomar decisões cruciais para sua família ou carreira.","orderIndex":1},{"id":"b15","title":"3. A Coroa da Vida Prometida aos que Amam a Deus","biblicalReference":"Tiago 1:12","explanation":"Bem-aventurado o homem que suporta a provação com integridade; após ser aprovado, receberá o galardão eterno.","illustration":"O ourives que aquece o ouro até conseguir ver o reflexo nítido do seu próprio rosto no metal depurado.","application":"Aguente firme: Deus está lapidando o seu caráter para manifestar a glória dEle.","orderIndex":2}],"conclusion":"As provações não vêm para destruir o crente, mas para queimar a escória e revelar o ouro precioso da fé.","appeal":"Consagre suas dores ao Senhor e peça a força perseverante do Espírito Santo."}'::jsonb
  ),
  (
    'Permanecendo na Videira Verdadeira',
    'O Segredo da Frutificação e da Dependência Contínua',
    'João 15:1-8',
    'Expositivo',
    ARRAY['Discipulado', 'Comunhão', 'Fruto', 'Jesus']::TEXT[],
    '{"introduction":"Nas últimas horas antes da cruz, Jesus revela o segredo de uma vida espiritual fecunda: a conexão vital com Ele.","blocks":[{"id":"b16","title":"1. Jesus, a Videira; o Pai, o Agricultor","biblicalReference":"João 15:1-2","explanation":"O Pai limpa e poda o ramo que dá fruto para que produza ainda mais. A poda dói, mas gera abundância futura.","illustration":"O vinhedo na primavera que parece despido e ferido após a poda, mas floresce carregado de cachos no verão.","application":"Não murmure contra a disciplina ou as podas de Deus; elas visam a sua maior fertilidade espiritual.","orderIndex":0},{"id":"b17","title":"2. Sem Mim Nada Podeis Fazer","biblicalReference":"João 15:4-5","explanation":"O ramo não tem vida autônoma. Cortado da seiva da videira, ele seca, morre e é recolhido para o fogo.","illustration":"Uma lâmpada desconectada da tomada: pode ser bonita e cara, mas é incapaz de emitir luz por si mesma.","application":"Reconheça sua dependência total de Jesus para amar, perdoar e exercer qualquer ministério.","orderIndex":1},{"id":"b18","title":"3. A Glória do Pai Manifesta na Abundância de Frutos","biblicalReference":"João 15:7-8","explanation":"Se permanecerdes em Mim e Minhas palavras em vós, pedireis o que quiserdes e vos será feito.","illustration":"A árvore frutífera que sacia os transeuntes famintos sem cobrar nada pelo seu fruto.","application":"Cultive a oração e a Palavra diária para que seu testemunho gere frutos visíveis e duradouros.","orderIndex":2}],"conclusion":"Frutificar não é fruto de esforço humano estressante, mas o resultado natural de permanecer conectado à raiz divina.","appeal":"Reate sua intimidade e permanência diária em Cristo nesta noite."}'::jsonb
  ),
  (
    'Revestidos do Novo Homem',
    'A Transformação Prática que Reflete o Caráter de Cristo',
    'Colossenses 3:1-17',
    'Expositivo',
    ARRAY['Santidade', 'Família', 'Comportamento', 'Caráter']::TEXT[],
    '{"introduction":"Ressuscitados com Cristo, os cristãos são chamados a pensar nas coisas do alto e trocar as velhas vestes do pecado pelas vestes da graça.","blocks":[{"id":"b19","title":"1. O Foco nas Coisas do Alto","biblicalReference":"Colossenses 3:1-4","explanation":"Nossa verdadeira vida está oculta com Cristo em Deus. Nosso padrão ético não é a cultura terrena, mas o Reino celestial.","illustration":"A bússola do marinheiro que aponta invariavelmente para o norte magnético, não importa a turbulência das ondas.","application":"Avalie onde seu tempo, pensamentos e ambições estão concentrados nesta semana.","orderIndex":0},{"id":"b20","title":"2. O Despojar das Velhas Vestes Carnais","biblicalReference":"Colossenses 3:5-9","explanation":"Fazer morrer a prostituição, ira, malícia, difamação e a mentira. São roupas sujas de um passado que já foi sepultado.","illustration":"Lázaro saindo do túmulo: Jesus ordenou ''desatai-o e deixai-o ir'', removendo as faixas de morte.","application":"Renuncie hoje a hábitos secretos e conversas tóxicas que contradizem sua nova vida em Cristo.","orderIndex":1},{"id":"b21","title":"3. As Roupas da Graça: Compaixão, Humildade e Amor","biblicalReference":"Colossenses 3:12-14","explanation":"Como eleitos de Deus, revesti-vos de ternura, paciência e perdão mútuo. O amor é o vínculo da perfeição.","illustration":"O casaco quente que protege a família inteira da geada do ressentimento e da dureza de coração.","application":"Pratique o perdão voluntário com as pessoas mais difíceis da sua própria casa.","orderIndex":2}],"conclusion":"Tudo o que fizerdes, por palavra ou por obra, fazei-o em nome do Senhor Jesus, dando graças a Deus Pai.","appeal":"Abra mão do velho homem e vista-se da presença de Cristo agora mesmo."}'::jsonb
  ),
  (
    'Combatendo o Bom Combate da Fé',
    'Fidelidade, Perseverança e o Legado que Permanece',
    '2 Timóteo 4:6-8',
    'Expositivo',
    ARRAY['Perseverança', 'Liderança', 'Fidelidade', 'Coroa']::TEXT[],
    '{"introduction":"Nas celas frias de Roma, prestes a ser martirizado, Paulo olha para trás com paz e para a frente com alegre expectativa.","blocks":[{"id":"b22","title":"1. A Vida como Libação Ofertada a Deus","biblicalReference":"2 Timóteo 4:6","explanation":"O apóstolo não vê sua morte como uma tragédia imposta pelo imperador, mas como uma oferta derramada voluntariamente sobre o altar.","illustration":"O azeite derramado sobre o sacrifício no tabernáculo cujo aroma suave subia até a presença de Deus.","application":"Viva sua rotina, profissão e ministério como atos diários de adoração consagrada ao Senhor.","orderIndex":0},{"id":"b23","title":"2. A Tríplice Vitória: Combate, Carreira e Fé Guardada","biblicalReference":"2 Timóteo 4:7","explanation":"Lutei o bom combate da justiça; completei a rota estabelecida por Deus para mim; preservei a integridade do Evangelho.","illustration":"O maratonista olímpico que cruza a linha de chegada exausto mas com a tocha da fé acesa nas mãos.","application":"Não desista no meio do percurso; a fidelidade de hoje garante a honra de amanhã.","orderIndex":1},{"id":"b24","title":"3. A Coroa da Justiça e o Justo Juiz","biblicalReference":"2 Timóteo 4:8","explanation":"O galardão eterno não é reservado apenas a grandes apóstolos, mas a todos os que amam a manifestação gloriosa de Cristo.","illustration":"A coroa de louros que nunca murcha aguardando os servos fiéis nos portões da Nova Jerusalém.","application":"Mantenha seus olhos na recompensa eterna quando o cansaço do caminho tentar desanimar você.","orderIndex":2}],"conclusion":"Mais importante do que como começamos a jornada cristã é como terminamos: guardando a fé até o último suspiro.","appeal":"Reafirme o seu compromisso de lealdade a Cristo até a linha de chegada."}'::jsonb
  ),
  (
    'A Supremacia do Amor Cristão',
    'O Caminho Mais Excelente da Igreja de Deus',
    '1 Coríntios 13:1-13',
    'Expositivo',
    ARRAY['Amor', 'Edificação', 'Maturidade', 'Igreja']::TEXT[],
    '{"introduction":"Em uma igreja fascinada por dons espirituais espetaculares, Paulo ensina que o poder sem amor é mero ruído e vaidade vazia.","blocks":[{"id":"b25","title":"1. A Inutilidade dos Dons sem a Essência do Amor","biblicalReference":"1 Coríntios 13:1-3","explanation":"Falar línguas, profetizar e doar bens sem amor ágape nos reduz a um sino barulhento e a nada de valor eterno.","illustration":"Um címbalo estridente que incomoda a todos em vez de produzir melodia edificante.","application":"Exerça seus talentos na igreja sempre motivado pela compaixão e pelo bem do próximo.","orderIndex":0},{"id":"b26","title":"2. O Retrato Perfeito do Amor Ágape","biblicalReference":"1 Coríntios 13:4-7","explanation":"O amor é paciente, benigno; não inveja, não se ensoberbece, não busca seus próprios interesses e tudo suporta.","illustration":"Substitua a palavra ''amor'' pelo nome de Jesus no texto e você verá a exata encarnação do Evangelho.","application":"Avalie seus relacionamentos familiares à luz da paciência e da renúncia ao egoísmo.","orderIndex":1},{"id":"b27","title":"3. O Amor que Nunca Acaba","biblicalReference":"1 Coríntios 13:8-13","explanation":"Profecias e línguas cessarão quando vier o que é perfeito; mas a fé, a esperança e o amor permanecem. O maior é o amor.","illustration":"O andaime que é desmontado quando a catedral eterna é concluída; o amor é a própria catedral.","application":"Invista tempo e energia naquilo que ecoará pela eternidade: amar a Deus e amar as pessoas.","orderIndex":2}],"conclusion":"O amor cristão não é um sentimento passageiro; é uma decisão sobrenatural viabilizada pelo Espírito Santo.","appeal":"Peça que Deus derrame o amor ágape no seu coração para sarar mágoas e restaurar pontes."}'::jsonb
  ),
  (
    'O Guarda que Não Dorme',
    'A Proteção Incessante do Deus Altíssimo',
    'Salmo 121:1-8',
    'Expositivo',
    ARRAY['Proteção', 'Salmos', 'Peregrinação', 'Segurança']::TEXT[],
    '{"introduction":"O cântico dos peregrinos a caminho de Jerusalém: enfrentando montanhas perigosas e salteadores com os olhos no Criador.","blocks":[{"id":"b28","title":"1. O Olhar Erguido Para Além dos Montes","biblicalReference":"Salmo 121:1-2","explanation":"Os montes podiam conter esconderijos de inimigos ou altares pagãos. O socorro do crente vem do Criador dos montes, e não da criação.","illustration":"O viajante que não se deixa hipnotizar pelo abismo do despenhadeiro porque foca no cume seguro da colina.","application":"Não busque segurança primária em contatos políticos ou dinheiro; seu socorro vem do Senhor.","orderIndex":0},{"id":"b29","title":"2. O Sentinela que Não Cochila","biblicalReference":"Salmo 121:3-4","explanation":"O Guarda de Israel (Shomer Yisrael) não tosqueneja nem dorme. Ele não vacila nem cansa nas vigílias da noite.","illustration":"O guarda da muralha que vigia a cidade enquanto os cidadãos dormem em segurança em suas camas.","application":"Durma em paz esta noite: aquele que cuida do seu destino está de olhos abertos sobre a sua casa.","orderIndex":1},{"id":"b30","title":"3. A Sombra Protetora em Toda a Jornada","biblicalReference":"Salmo 121:5-8","explanation":"O Senhor é sombra à direita contra a insolação do dia e o frio da noite. Guarda tua entrada e tua saída, agora e para sempre.","illustration":"A coluna de nuvem e de fogo que acompanhou o povo de Israel pelo calor e deserto do Sinai.","application":"Caminhe com confiança: nenhuma força climática ou espiritual pode frustrar os planos de Deus para você.","orderIndex":2}],"conclusion":"Não há estrada perigosa demais quando o próprio Deus dos céus é o nosso guarda e protetor pessoal.","appeal":"Entregue a sua saída e a sua chegada nas mãos protetoras do Senhor Jesus."}'::jsonb
  ),
  (
    'Olhando Firmemente Para Jesus',
    'Desembaraçando-se do Peso para Correr a Carreira da Fé',
    'Hebreus 12:1-3',
    'Expositivo',
    ARRAY['Fé', 'Foco', 'Jesus', 'Perseverança']::TEXT[],
    '{"introduction":"A vida cristã é comparada a uma corrida no estádio olímpico com uma nuvem de testemunhas nas arquibancadas celestiais.","blocks":[{"id":"b31","title":"1. Livrando-se de Todo Peso e do Pecado que Cerceia","biblicalReference":"Hebreus 12:1a","explanation":"Nem todo peso é pecado condenável, mas qualquer coisa que roube o fôlego da consagração precisa ser deixada para trás.","illustration":"Nenhum atleta corre a prova dos 100 metros vestindo casaco de inverno e sapatos de chumbo.","application":"Identifique hoje os entretenimentos, distrações ou culpas que estão pesando nos seus ombros e liberte-se.","orderIndex":0},{"id":"b32","title":"2. A Fixação Inabalável dos Olhos no Autor e Consumador da Fé","biblicalReference":"Hebreus 12:2","explanation":"Jesus suportou a cruz desprezando a vergonha pela alegria que Lhe estava proposta, assentando-se à destra do Pai.","illustration":"O piloto que fixa os olhos na pista iluminada em noite fechada ignorando as turbulências da tempestade.","application":"Tire o foco dos defeitos das pessoas ou líderes e fixe o olhar na perfeição de Jesus Cristo.","orderIndex":1},{"id":"b33","title":"3. A Cura Contra o Cansaço e Desfalecimento da Alma","biblicalReference":"Hebreus 12:3","explanation":"Considerai Aquele que suportou tamanha oposição dos pecadores contra Si mesmo, para que não vos canseis mentalmente.","illustration":"Lembrar dos cravos nas mãos do Mestre renova a disposição de quem sofre pequenas afrontas cotidianas.","application":"Encontre novo ânimo na contemplação da cruz quando sentir vontade de jogar a toalha.","orderIndex":2}],"conclusion":"Quem corre olhando para trás tropeça; quem corre olhando para os lados se distrai; quem corre olhando para Jesus vence.","appeal":"Olhe para Cristo agora e receba novo fôlego para prosseguir até o fim."}'::jsonb
  ),
  (
    'O Fruto do Espírito Santo',
    'A Transformação Visível do Caráter pelo Toque da Graça',
    'Gálatas 5:22-26',
    'Expositivo',
    ARRAY['Espírito Santo', 'Santidade', 'Caráter', 'Discipulado']::TEXT[],
    '{"introduction":"Paulo contrasta a lista sombria das obras da carne com a sinfonia luminosa do Fruto do Espírito na vida do crente.","blocks":[{"id":"b34","title":"1. A Natureza Singular do Fruto Espiritual","biblicalReference":"Gálatas 5:22a","explanation":"O apóstolo usa o singular ''fruto'' (karpos), indicando um único cacho divino com nove facetas harmoniosas e inseparáveis.","illustration":"Uma laranja com gomos distintos, todos nutridos pela mesma seiva do caule principal.","application":"Não escolha virtudes isoladas; permita que o Espírito Santo modele todo o seu temperamento.","orderIndex":0},{"id":"b35","title":"2. As Três Dimensões do Fruto: Para Deus, o Próximo e Si Mesmo","biblicalReference":"Gálatas 5:22-23","explanation":"Amor, alegria e paz (para com Deus); longanimidade, benignidade e bondade (com o próximo); fidelidade, mansidão e domínio próprio (consigo).","illustration":"O perfume das flores que atrai a todos pelo aroma agradável e dissipa o odor do egoísmo.","application":"Examine como você trata as pessoas sob estresse: o domínio próprio e a mansidão estão presentes?","orderIndex":1},{"id":"b36","title":"3. A Crucificação da Carne e o Andar em Sintonia com o Espírito","biblicalReference":"Gálatas 5:24-25","explanation":"Os que são de Cristo crucificaram as paixões mundanas. Se vivemos pelo Espírito, devemos marchar no compasso dEle.","illustration":"Dois dançarinos em perfeita sincronia: quando um conduz com maestria, os passos do outro fluem sem tropeços.","application":"Entregue a direção das suas reações e palavras ao controle suave do Consolador.","orderIndex":2}],"conclusion":"O fruto do Espírito é a assinatura de Deus no caráter de quem caminha intimamente com Ele.","appeal":"Abra o seu coração e peça uma nova unção geradora de frutos espirituais."}'::jsonb
  ),
  (
    'Humildade, Resistência e Restauração',
    'O Caminho Divino Para a Vitória Sobre o Inimigo',
    '1 Pedro 5:6-10',
    'Expositivo',
    ARRAY['Humildade', 'Vigilância', 'Restauração', 'Vitória']::TEXT[],
    '{"introduction":"Pedro escreve a uma igreja sob o fogo da perseguição e traça o mapa da vitória espiritual.","blocks":[{"id":"b37","title":"1. A Humilhação Debaixo da Potente Mão de Deus","biblicalReference":"1 Pedro 5:6-7","explanation":"A soberba atrai a oposição de Deus, mas a humildade atrai Sua graça. Lançar a ansiedade nEle porque Ele cuida de nós.","illustration":"O barco ancorado no cais: as cordas transmitem a tensão à terra firme, e não às ondas.","application":"Reconheça suas limitações diante do Criador e confie no Seu tempo perfeito de exaltação.","orderIndex":0},{"id":"b38","title":"2. A Sobriedade e a Resistência Contra o Leão Rugidor","biblicalReference":"1 Pedro 5:8-9","explanation":"O diabo ruge buscando a quem possa devorar. Ele não tem poder de tragar quem está desperto e firme na fé.","illustration":"O leão caça a presa isolada e distraída na savana; quem anda em bando sob a liderança do pastor está seguro.","application":"Mantenha a comunhão com a igreja local e feche todas as portas do pecado em sua vida.","orderIndex":1},{"id":"b39","title":"3. A Quádrupla Promessa do Deus de Toda a Graça","biblicalReference":"1 Pedro 5:10","explanation":"Depois de sofrerdes um pouco, o próprio Deus vos aperfeiçoará, firmará, fortificará e fundamentará.","illustration":"O edifício reforçado com vigas de aço após o terremoto, tornando-se mais forte do que antes da abalo.","application":"Receba a convicção de que suas dores atuais resultarão em estabilidade espiritual duradoura.","orderIndex":2}],"conclusion":"As provações são passageiras, mas o aperfeiçoamento forjado por Deus na fornalha é eterno.","appeal":"Venha aos pés do Senhor e receba restauração completa para suas feridas."}'::jsonb
  ),
  (
    'A Mente de Cristo e a Glória da Humildade',
    'O Paradoxo da Grandeza através do Serviço e Desprendimento',
    'Filipenses 2:5-11',
    'Expositivo',
    ARRAY['Cristologia', 'Humildade', 'Serviço', 'Exaltação']::TEXT[],
    '{"introduction":"O mais profundo poema cristológico da Bíblia (Kenosis) mostra o caminho da verdadeira honra no Reino dos Céus.","blocks":[{"id":"b40","title":"1. A Atitude Interior: Não Julgar por Usurpação Ser Igual a Deus","biblicalReference":"Filipenses 2:5-6","explanation":"Mesmo sendo Deus por natureza, Jesus não se apegou aos Seus privilégios divinos com avareza.","illustration":"Um rei benevolente que despe sua coroa de ouro para vestir os trapos de seus súditos doentes.","application":"Abra mão do orgulho e da vaidade de exigir sempre ter a razão em discussões familiares.","orderIndex":0},{"id":"b41","title":"2. A Descida Abissal: Esvaziamento, Servo e Morte de Cruz","biblicalReference":"Filipenses 2:7-8","explanation":"Kenosis: esvaziou-se a Si mesmo, assumindo a forma de servo e humilhando-se até a morte infame de cruz.","illustration":"A cruz romana: símbolo de maldição e escárnio público transformado em altar de redenção eterna.","application":"Sirva aos irmãos nos bastidores sem necessidade de aplausos ou holofotes humanos.","orderIndex":1},{"id":"b42","title":"3. A Soberana Exaltação e o Nome Sobre Todo Nome","biblicalReference":"Filipenses 2:9-11","explanation":"Por isso Deus O exaltou soberanamente. Todo joelho se dobrará e toda língua confessará que Jesus Cristo é o Senhor.","illustration":"A coroação do Cordeiro nos céus aplaudida por miríades de anjos e anciãos.","application":"Dobre seu joelho voluntariamente hoje em adoração antes do dia em que todos terão de fazê-lo.","orderIndex":2}],"conclusion":"No Reino de Deus, o caminho para cima começa descendo; quem se humilha é exaltado pelo Pai.","appeal":"Adote a mente humilde de Cristo e deixe Deus conduzir a sua promoção."}'::jsonb
  ),
  (
    'A Graça Escandalosa do Pai Pródigo em Amor',
    'O Resgate do Filho Rebelde e o Alerta ao Irmão Religioso',
    'Lucas 15:11-32',
    'Expositivo',
    ARRAY['Graça', 'Perdão', 'Paternidade', 'Salvação']::TEXT[],
    '{"introduction":"A parábola mais comovente contada por Jesus retrata não a ruína de um jovem, mas o coração apaixonado de um Pai misericordioso.","blocks":[{"id":"b43","title":"1. A Ilusão da Independência e o Chiqueiro dos Porcos","biblicalReference":"Lucas 15:11-16","explanation":"Pedir a herança com o pai vivo equivalia a desejar sua morte. O pecado promete liberdade, mas escraviza na carência.","illustration":"O jovem faminto desejando a comida dos porcos impuros: o retrato da alma distante do altar de Deus.","application":"Reconheça a futilidade das ilusões deste mundo e caia em si antes de chegar ao fundo do poço.","orderIndex":0},{"id":"b44","title":"2. O Retorno Quebrantado e o Abraço com Beijos de Graça","biblicalReference":"Lucas 15:17-24","explanation":"O pai corre ao encontro do filho (ato incomum para um patriarca oriental), coloca a melhor túnica, anel e sandálias.","illustration":"As vestes limpas do pai cobrindo o cheiro imundo de porcos que o filho trazia no corpo.","application":"Volte para o Pai exatamente como você está; a graça dEle apaga o seu passado em um instante.","orderIndex":1},{"id":"b45","title":"3. O Perigo da Religiosidade Amarga do Filho Mais Velho","biblicalReference":"Lucas 15:25-32","explanation":"O filho mais velho estava dentro da casa, mas o seu coração estava tão longe do pai quanto o do irmão pródigo.","illustration":"O crente que cumpre tarefas na igreja por obrigação e ressente a celebração da conversão de novos pecadores.","application":"Limpe seu coração de ciúmes e celebre com júbilo o retorno dos perdidos à casa do Pai.","orderIndex":2}],"conclusion":"Deus não é um capataz austero; Ele é o Pai que festeja com banquete o regresso de cada filho amado.","appeal":"Dê o passo de volta para casa hoje: os braços do Pai estão abertos para você."}'::jsonb
  ),
  (
    'A Fé que Canta Mesmo na Escassez',
    'Regozijo Incondicional no Deus da Nossa Salvação',
    'Habacuque 3:17-19',
    'Expositivo',
    ARRAY['Fé', 'Louvor', 'Esperança', 'Vitória']::TEXT[],
    '{"introduction":"Habacuque começou seu livro questionando os caminhos de Deus no meio da crise e termina com o cântico de fé mais elevado do Antigo Testamento.","blocks":[{"id":"b46","title":"1. O Cenário da Falência e da Seca Total","biblicalReference":"Habacuque 3:17","explanation":"Ainda que a figueira não floresça, nem haja fruto na vide; falhe o produto da oliveira e os campos não produzam mantimento.","illustration":"O celeiro vazio e os currais sem rebanhos: o deserto econômico mais assustador.","application":"Não baseie o seu louvor no saldo bancário ou nas circunstâncias favoráveis da vida.","orderIndex":0},{"id":"b47","title":"2. Todavia, Eu Me Alegrarei no Deus da Minha Salvação","biblicalReference":"Habacuque 3:18","explanation":"A conjunção ''todavia'' rompe a lógica terrena. A alegria do crente não está no que Deus dá, mas em Quem Deus é.","illustration":"Paulo e Silas cantando hinos à meia-noite na prisão de Filipos com os pés presos no tronco e costas ensanguentadas.","application":"Entoe um cântico de louvor espontâneo mesmo que o dia tenha sido difícil e cansativo.","orderIndex":1},{"id":"b48","title":"3. Os Pés de Corça e as Alturas Espirituais","biblicalReference":"Habacuque 3:19","explanation":"O Senhor Deus é a minha fortaleza; faz os meus pés como os das corças e me faz andar nas alturas.","illustration":"A corça que pisa firme em rochedos pontiagudos onde predadores escorregam e caem no abismo.","application":"Receba de Deus pés firmes para saltar sobre as crises e viver no nível superior da fé.","orderIndex":2}],"conclusion":"A verdadeira maturidade cristã é adorar a Deus não pelo que temos nas mãos, mas pela certeza de Quem Ele é.","appeal":"Louve a Deus no meio da sua luta e veja as cadeias espirituais se romperem."}'::jsonb
  ),
  (
    'As Bem-Aventuranças: A Ética do Reino',
    'A Felicidade Paradoxal e Verdadeira dos Discípulos de Jesus',
    'Mateus 5:1-12',
    'Expositivo',
    ARRAY['Reino de Deus', 'Discipulado', 'Sermão da Montanha', 'Felicidade']::TEXT[],
    '{"introduction":"No Sermão da Montanha, Jesus proclama o manifesto do Reino e vira de cabeça para baixo a definição mundana de sucesso.","blocks":[{"id":"b49","title":"1. Os Humildes de Espírito e os que Choram","biblicalReference":"Mateus 5:3-4","explanation":"Pobreza de espírito significa reconhecer falência espiritual diante da santidade de Deus. Choro pelo pecado atrai consolo divino.","illustration":"O publicano no templo que batia no peito e dizia ''Tem misericórdia de mim, pecador'' e saiu justificado.","application":"Venha a Deus sem pretensões de mérito próprio; a graça só entra por corações quebrantados.","orderIndex":0},{"id":"b50","title":"2. Os Mansos e os que Têm Fome e Sede de Justiça","biblicalReference":"Mateus 5:5-6","explanation":"Mansidão bíblica não é fraqueza, mas poder sob controle voluntário. O apetite por retidão será fartamente saciado pelo Pai.","illustration":"Um garanhão selvagem e poderoso que aprende a obedecer suavemente aos toques da rédea do cavaleiro.","application":"Controle seus impulsos de vingança e alimente sua fome diária pela santidade e retidão.","orderIndex":1},{"id":"b51","title":"3. Os Misericordiosos, Limpos de Coração e Pacificadores","biblicalReference":"Mateus 5:7-9","explanation":"Quem semeia misericórdia colhe misericórdia. Os limpos de coração verão a Deus; os que promovem a paz são filhos do Altíssimo.","illustration":"Um espelho de cristal polido que reflete sem distorções os raios do sol da justiça.","application":"Seja um construtor de pontes e apaziguador de conflitos em sua igreja e ambiente de trabalho.","orderIndex":2}],"conclusion":"A felicidade que Jesus oferece não é euforia passageira, mas a solidez inabalável de pertencer ao Reino de Deus.","appeal":"Entregue seus padrões mundanos no altar e viva a genuína bem-aventurança de Cristo."}'::jsonb
  ),
  (
    'Renovando as Forças Como a Águia',
    'Descanso, Voo Alto e Esperança Para os Cansados',
    'Isaías 40:28-31',
    'Expositivo',
    ARRAY['Esperança', 'Renovo', 'Cansaço', 'Vitória']::TEXT[],
    '{"introduction":"O profeta Isaías consola o povo exilado na Babilônia, lembrando que o Criador dos confins da terra nunca se cansa.","blocks":[{"id":"b52","title":"1. A Inesgotável Energia do Criador Soberano","biblicalReference":"Isaías 40:28-29","explanation":"Não sabes? Não ouviste? Ele não se cansa nem Se fatiga; dá força aos cansados e multiplica as forças a quem não tem vigor.","illustration":"O sol que queima há milênios sem perder um único raio de luz; a fonte divina é infinitamente maior.","application":"Pare de tentar carregar suas crises na força do próprio braço e recorra à fonte inesgotável.","orderIndex":0},{"id":"b53","title":"2. O Limite das Forças Humanas Mais Vigorosas","biblicalReference":"Isaías 40:30","explanation":"Até os jovens se cansam e os moços caem exaustos. A juventude biológica falha, mas a graça sustenta.","illustration":"O atleta mais jovem que desaba exausto se não ingerir água e alimentos vitais.","application":"Reconheça sua vulnerabilidade física e emocional e peça o refrigério do Espírito Santo.","orderIndex":1},{"id":"b54","title":"3. A Troca Sobrenatural: Os que Esperam no Senhor","biblicalReference":"Isaías 40:31","explanation":"A palavra hebraica para ''esperar'' (qavah) carrega a ideia de entrelaçar fios para formar uma corda inquebrável. Troca de cansaço por vigor.","illustration":"A águia que não bate asas freneticamente na tempestade, mas abre as asas e plana sobre as correntes térmicas ascendentes.","application":"Espere em oração reverente e deixe as correntes da graça de Deus elevarem o seu voo acima dos problemas.","orderIndex":2}],"conclusion":"Quem espera no Senhor corre sem cansar e caminha sem desfalecer rumo ao cumprimento das promessas.","appeal":"Venha receber asas de águia para superar o cansaço da sua alma hoje."}'::jsonb
  ),
  (
    'A Mesa da Memória, Comunhão e Esperança',
    'Os Três Olhares da Santa Ceia do Senhor',
    '1 Coríntios 11:23-26',
    'Temático',
    ARRAY['Santa Ceia', 'Comunhão', 'Aliança', 'Cruz', 'Sacrifício']::TEXT[],
    '{"introduction":"A mesa da Ceia não é mero ritual litúrgico; é o memorial solene da nossa redenção instituído pelo próprio Jesus.","blocks":[{"id":"b55","title":"1. O Olhar Para Trás: A Memória do Sacrifício na Cruz","biblicalReference":"1 Coríntios 11:24","explanation":"Fazei isto em memória de Mim. O pão partido e o cálice derramado nos lembram do alto preço pago pelo nosso perdão.","illustration":"O memorial dos heróis de guerra com a chama eterna acesa; a cruz é o nosso memorial definitivo.","application":"Aproxime-se da mesa com reverência profunda e gratidão por tudo o que Cristo suportou em seu lugar.","orderIndex":0},{"id":"b56","title":"2. O Olhar Para Dentro e Para os Lados: Exame e Comunhão","biblicalReference":"1 Coríntios 11:28-29","explanation":"Examine-se o homem a si mesmo. Discernir o corpo de Cristo envolve pedir perdão a Deus e acertar contas com os irmãos.","illustration":"Um banquete de família onde mágoas são dissolvidas antes de partilhar o mesmo pão à mesa.","application":"Libere perdão a quem o ofendeu antes de estender as mãos para receber os elementos sagrados.","orderIndex":1},{"id":"b57","title":"3. O Olhar Para Frente: A Esperança da Volta Triunfal","biblicalReference":"1 Coríntios 11:26","explanation":"Anunciais a morte do Senhor até que Ele venha. A Ceia é uma refeição provisória que aponta para as Bodas do Cordeiro.","illustration":"O noivo que envia presentes à noiva enquanto prepara a festa do casamento definitivo.","application":"Renove sua vigilância espiritual crendo que em breve celebraremos face a face com Jesus.","orderIndex":2}],"conclusion":"Na Ceia nos alimentamos da graça do passado, nos fortalecemos na comunhão do presente e vislumbramos a glória do futuro.","appeal":"Venha participar da mesa da graça com coração puro e renovado em Cristo."}'::jsonb
  ),
  (
    'Edificando o Altar da Família',
    'A Casa Cristã Como Santuário de Deus e Refúgio Seguro',
    'Josué 24:14-15',
    'Temático',
    ARRAY['Família', 'Casamento', 'Culto Doméstico', 'Aliança']::TEXT[],
    '{"introduction":"No entardecer de sua liderança sobre Israel, Josué convoca as tribos e estabelece o marco inegociável da sua casa.","blocks":[{"id":"b58","title":"1. A Escolha Inegociável da Liderança Espiritual","biblicalReference":"Josué 24:15a","explanation":"Escolhei hoje a quem sirvais. A neutralidade espiritual na família não existe; se você não influenciar seus filhos, o mundo o fará.","illustration":"O timoneiro do navio que precisa manter a bússola firme para a embarcação não naufragar nas correntezas.","application":"Pais e mães, reassumam a autoridade amorosa de orar e guiar espiritualmente seus lares.","orderIndex":0},{"id":"b59","title":"2. O Pacto Sagrado: Eu e a Minha Casa Serviremos ao Senhor","biblicalReference":"Josué 24:15b","explanation":"Servir significa dedicar os talentos, recursos, prioridades e ambiente doméstico à glória do Senhor.","illustration":"A Arca de Noé: Deus não salvou indivíduos desvinculados, Ele salvou a família inteira da destruição.","application":"Institua o culto doméstico e momentos semanais de leitura da Bíblia ao redor da mesa da sua casa.","orderIndex":1},{"id":"b60","title":"3. O Legado que Atravessa Gerações","biblicalReference":"Deuteronômio 6:6-9","explanation":"Ensine as palavras aos teus filhos assentado em casa, andando pelo caminho, ao deitar e ao levantar.","illustration":"As raízes profundas do carvalho que suportam ventos furiosos porque foram nutridas desde cedo na boa terra.","application":"Deixe como maior herança aos seus filhos o testemunho inabalável de sua fé em Cristo.","orderIndex":2}],"conclusion":"As maiores vitórias de um ministério não são conquistadas sobre púlpitos públicos, mas no chão da própria casa.","appeal":"Dedique o seu lar a Deus nesta noite e quebre qualquer jugo de divisão familiar."}'::jsonb
  ),
  (
    'O Cordão de Três Dobras no Matrimônio',
    'Blindando o Casamento com a Presença de Cristo',
    'Eclesiastes 4:9-12',
    'Temático',
    ARRAY['Casamento', 'Amor', 'Unidade', 'Relacionamento']::TEXT[],
    '{"introduction":"O casamento foi criado por Deus no Éden para ser refúgio e complemento, mas precisa de um terceiro elemento indispensável para não arrebentar.","blocks":[{"id":"b61","title":"1. O Valor da Parceria: Melhor É Serem Dois do que Um","biblicalReference":"Eclesiastes 4:9-10","explanation":"Porque têm melhor paga pelo seu trabalho. Se um cair, o outro levanta o seu companheiro; ai do que estiver só.","illustration":"Duas tochas que unidas produzem o dobro de calor e iluminam caminhos escuros.","application":"Substitua a competição no casamento por cooperação diária e palavras de incentivo mútuo.","orderIndex":0},{"id":"b62","title":"2. O Calor da Conexão Contra o Frio da Indiferença","biblicalReference":"Eclesiastes 4:11","explanation":"Se dois dormirem juntos, eles se aquentarão; mas um só como se aquentará? A frieza emocional destrói mais lares do que crises externas.","illustration":"A fogueira que morre se os tições forem afastados uns dos outros.","application":"Proteja o tempo de intimidade e diálogo com seu cônjuge dos ladrões de atenção como celulares e redes sociais.","orderIndex":1},{"id":"b63","title":"3. O Terceiro Fio: Cristo no Centro da Aliança","biblicalReference":"Eclesiastes 4:12","explanation":"O cordão de três dobras não se quebra facilmente. Quando marido e mulher se achegam a Cristo, ficam mais próximos um do outro.","illustration":"O triângulo: à medida que os dois vértices da base sobem em direção ao vértice superior, a distância entre eles encurta.","application":"Orem juntos todos os dias como casal e deixem Jesus mediar as decisões e conflitos conjugais.","orderIndex":2}],"conclusion":"Um casamento blindado pela presença de Cristo resiste às crises financeiras, tempestades emocionais e desgastes do tempo.","appeal":"Consagre seu casamento a Deus e renove os votos de amor e respeito."}'::jsonb
  ),
  (
    'Instruindo a Criança no Caminho da Vida',
    'O Maior Investimento e Legado Espiritual dos Pais',
    'Provérbios 22:6',
    'Temático',
    ARRAY['Filhos', 'Educação', 'Discipulado', 'Família']::TEXT[],
    '{"introduction":"A infância é o período de maior absorção moral e espiritual da vida. O que gravamos no coração de uma criança ecoará por décadas.","blocks":[{"id":"b64","title":"1. Instruir no Caminho em que Deve Andar","biblicalReference":"Provérbios 22:6a","explanation":"Não diz ''aponte o caminho'', mas ensine ''no caminho''. Os filhos aprendem mais pelo que veem seus pais praticando do que pelo que ouvem em sermões.","illustration":"As pegadas na neve fresca: os passos dos pequenos buscam exatamente os passos firmes deixados pelos pais.","application":"Seja um modelo autêntico de oração, integridade nos negócios e amor à igreja dentro da sua casa.","orderIndex":0},{"id":"b65","title":"2. A Disciplina Amorosa e o Diálogo que Edifica","biblicalReference":"Efésios 6:4","explanation":"Pais, não provoqueis a ira de vossos filhos, mas criai-os na disciplina e admoestação do Senhor. Firmeza sem amargura.","illustration":"A cerca de proteção no penhasco: os filhos se sentem seguros quando conhecem os limites estabelecidos pelo amor.","application":"Corrija seus filhos para educar e restaurar, nunca no calor da raiva descontrolada.","orderIndex":1},{"id":"b66","title":"3. A Promessa Duradoura: Até a Velhice Não se Desviará","biblicalReference":"Provérbios 22:6b","explanation":"A semente da Palavra plantada no coração infantil cria raízes eternas que nem as tempestades da juventude apagam.","illustration":"O barco que enfrenta ventanias distantes mas retorna seguro ao porto seguro onde ancorou suas primeiras memórias.","application":"Nunca cesse de interceder pelos seus filhos, crendo no resgate infalível da graça divina.","orderIndex":2}],"conclusion":"Cuidar dos filhos hoje é preparar as colunas da igreja e da sociedade de amanhã.","appeal":"Oração de cobertura espiritual e bênção patriarcal sobre todas as crianças e jovens."}'::jsonb
  ),
  (
    'Corações Fiéis e Generosos no Altar',
    'Mordomia Cristã, Finanças e Quebra do Materialismo',
    '2 Coríntios 9:6-8',
    'Temático',
    ARRAY['Finanças', 'Generosidade', 'Mordomia', 'Fé']::TEXT[],
    '{"introduction":"Jesus falou mais sobre dinheiro e bens do que sobre céu e inferno porque o bolso é a área onde o senhorio de Deus é mais testado.","blocks":[{"id":"b67","title":"1. A Lei Universal da Semeadura Espiritual","biblicalReference":"2 Coríntios 9:6","explanation":"Quem semeia com fartura, com fartura também colherá. A avareza empobrece a alma, mas a generosidade abre as comportas da bênção.","illustration":"O agricultor que guarda todas as sementes no celeiro com medo de perdê-las e morre de fome no ano seguinte.","application":"Plante na obra missionária e no socorro aos necessitados com espírito voluntário e desprendido.","orderIndex":0},{"id":"b68","title":"2. O Doador Alegre Amado por Deus","biblicalReference":"2 Coríntios 9:7","explanation":"Cada um contribua segundo propôs no coração; não com tristeza ou por necessidade; porque Deus ama ao que dá com alegria.","illustration":"O presente oferecido com um sorriso radiante por uma criança ao seu pai no dia do aniversário.","application":"Contribua no dízimo e nas ofertas como um ato jubiloso de adoração e gratidão pelas bênçãos recebidas.","orderIndex":1},{"id":"b69","title":"3. A Suficiência de Toda a Graça para Toda Boa Obra","biblicalReference":"2 Coríntios 9:8","explanation":"Deus é poderoso para fazer abundar em vós toda a graça, a fim de que tenhamos sempre o suficiente para abençoar outros.","illustration":"O cano que conduz água pura: enquanto a água flui para saciar a sede de quem passa, o próprio cano permanece úmido e limpo.","application":"Seja um canal por onde os recursos de Deus fluem para abençoar vidas em vez de um reservatório estagnado.","orderIndex":2}],"conclusion":"A generosidade quebra o poder de Mamom sobre o nosso coração e alinha nossa vida à provisão do Reino.","appeal":"Entregue a administração de suas finanças a Deus e experimente a paz da mordomia fiel."}'::jsonb
  ),
  (
    'O Clamor dos Povos Não Alcançados',
    'O Imperativo Urgente da Grande Comissão Missionária',
    'Mateus 28:18-20',
    'Temático',
    ARRAY['Missões', 'Evangelismo', 'Grande Comissão', 'Igreja']::TEXT[],
    '{"introduction":"A Igreja de Cristo não existe para si mesma; ela é a agência missionária de Deus enviada a todos os povos e nações.","blocks":[{"id":"b70","title":"1. Toda a Autoridade nos Céus e na Terra","biblicalReference":"Mateus 28:18","explanation":"Jesus não nos envia desamparados. A ordem de ir é fundamentada na autoridade suprema do Rei ressurreto.","illustration":"O embaixador que fala com o peso diplomático e o exército de uma superpotência soberana por trás de si.","application":"Perca o medo de falar de Jesus no seu trabalho e faculdade: a autoridade de Cristo está com você.","orderIndex":0},{"id":"b71","title":"2. O Mandamento: Ide e Fazei Discípulos de Todas as Nações","biblicalReference":"Mateus 28:19","explanation":"Fazer discípulos envolve ensinar, batizar e caminhar junto. Missões envolve orar, contribuir e ir.","illustration":"Uma equipe de resgate nas águas turbulentas: ninguém fica parado apreciando a vista enquanto vidas se afogam.","application":"Adote um missionário em oração diária e envolva-se financeiramente com o envio de obreiros ao campo.","orderIndex":1},{"id":"b72","title":"3. A Promessa da Presença Inabalável Até o Fim dos Séculos","biblicalReference":"Mateus 28:20","explanation":"Eis que estou convosco todos os dias. A promessa da presença especial de Jesus acompanha a igreja que cumpre a missão.","illustration":"O comandante militar que marcha na vanguarda da tropa abrindo o caminho através das linhas inimigas.","application":"Experimente a manifestação do poder de Deus ao testemunhar da salvação a alguém nesta semana.","orderIndex":2}],"conclusion":"Ou a igreja é missionária e evangelística, ou ela trai o propósito fundamental da sua existência na terra.","appeal":"Responda ao chamado missionário: ore, contribua ou diga ''Eis-me aqui, envia-me a mim!''."}'::jsonb
  ),
  (
    'O Poder Oculto do Quarto Secreto',
    'Intimidade, Oração Eficaz e Respostas Visíveis',
    'Mateus 6:5-8',
    'Temático',
    ARRAY['Oração', 'Intimidade', 'Poder', 'Secreto']::TEXT[],
    '{"introduction":"A verdadeira estatura espiritual de um homem não é medida pelo que ele faz diante das multidões, mas pelo que ele é de joelhos no seu quarto secreto.","blocks":[{"id":"b73","title":"1. A Condenação da Hipocrisia Religiosa","biblicalReference":"Mateus 6:5","explanation":"Os hipócritas oravam nas esquinas para serem aplaudidos pelos homens. Já receberam sua mísera recompensa humana.","illustration":"Um ator que veste uma máscara bonita no palco, mas por trás da coxia não passa de um homem solitário.","application":"Livre-se da tentação de orar bonito para impressionar os outros; Deus busca a verdade no íntimo.","orderIndex":0},{"id":"b74","title":"2. Entra no Teu Quarto e Fecha a Porta","biblicalReference":"Mateus 6:6a","explanation":"Fechar a porta significa bloquear as distrações e ruídos do mundo exterior para se concentrar exclusivamente no Pai.","illustration":"A sala do trono do rei onde os guardas fecham as portas para uma audiência particular e confidencial.","application":"Separe 20 minutos diários sem celular para conversar de coração aberto com o Pai celeste.","orderIndex":1},{"id":"b75","title":"3. O Pai que Vê no Secreto Recompensará Publicamente","biblicalReference":"Mateus 6:6b","explanation":"As vitórias públicas na família, ministério e vida profissional são gestadas nas lágrimas derramadas no quarto escuro da oração.","illustration":"A fundação subterrânea de um arranha-céu: ninguém vê no subsolo, mas ela sustenta 50 andares acima da terra.","application":"Confie que nenhuma oração sincera feita em segredo é esquecida pelo coração de Deus.","orderIndex":2}],"conclusion":"Quando fechamos a porta da terra para orar, o céu abre as portas das suas bênçãos eternas sobre a nossa vida.","appeal":"Reabra hoje o seu altar particular do quarto secreto diante do Senhor."}'::jsonb
  ),
  (
    'A Esperança Inabalável que Vence a Morte',
    'Consolo Pastoral Para Corações Enlutados e a Certeza da Ressurreição',
    '1 Tessalonicenses 4:13-18',
    'Temático',
    ARRAY['Luto', 'Consolo', 'Esperança', 'Ressurreição']::TEXT[],
    '{"introduction":"A morte física é uma realidade dolorosa, mas para o crente em Jesus Cristo ela não é um ponto final trágico, apenas uma vírgula de esperança.","blocks":[{"id":"b76","title":"1. Não Se Entristecer Como os que Não Têm Esperança","biblicalReference":"1 Tessalonicenses 4:13","explanation":"O cristão chora e sente a dor da ausência física, mas o seu choro é regado pela certeza do reencontro na eternidade.","illustration":"A despedida no porto quando um ente querido viaja para uma pátria gloriosa onde logo nos reuniremos.","application":"Permita que o Consolador enxugue as lágrimas do seu coração ferido pela saudade.","orderIndex":0},{"id":"b77","title":"2. O Fundamento da Nossa Esperança: Jesus Morreu e Ressuscitou","biblicalReference":"1 Tessalonicenses 4:14","explanation":"Se cremos que Jesus ressuscitou, temos a garantia inquebrável de que Deus trará com Ele os que dormem no Senhor.","illustration":"O túmulo vazio em Jerusalém: a certidão de óbito da morte e a garantia da nossa vitória.","application":"Ancore sua fé na ressurreição corporal de Cristo que venceu o aguilhão do sepulcro.","orderIndex":1},{"id":"b78","title":"3. O Arrebatamento Glorioso e a Eternidade com o Senhor","biblicalReference":"1 Tessalonicenses 4:16-18","explanation":"Ao som da trombeta, os mortos em Cristo ressuscitarão primeiro; depois, nós os vivos seremos arrebatados para estar sempre com Ele.","illustration":"O sino que anuncia o fim da guerra e o retorno triunfal de todos os filhos do Rei para o banquete eterno.","application":"Consolai-vos uns aos outros com estas palavras e viva na expectativa alegre da glória porvir.","orderIndex":2}],"conclusion":"Em Cristo, a morte não tem a última palavra; a ressurreição e a vida eterna triunfarão para todo o sempre.","appeal":"Receba o consolo divino e entregue sua vida nas mãos do Senhor da Ressurreição."}'::jsonb
  ),
  (
    'A Liderança que Serve com a Toalha',
    'O Paradoxo da Grandeza Ministerial no Reino de Cristo',
    'Marcos 10:42-45',
    'Temático',
    ARRAY['Liderança', 'Serviço', 'Humildade', 'Ministério']::TEXT[],
    '{"introduction":"O mundo secular associa liderança a status, privilégios e controle; Jesus redefine liderança através da toalha e da bacia de lavar pés.","blocks":[{"id":"b79","title":"1. A Crítica ao Modelo Tirânico dos Governantes do Mundo","biblicalReference":"Marcos 10:42","explanation":"Os grandes das nações dominam e exercem autoridade pesada sobre os outros. Não será assim entre vós.","illustration":"O faraó do Egito que constrói pirâmides à custa do sangue e suor dos escravos indefesos.","application":"Renuncie a qualquer atitude de autoritarismo em sua casa, equipe de trabalho ou ministério.","orderIndex":0},{"id":"b80","title":"2. Quem Quiser Ser Grande, Seja o que Serve","biblicalReference":"Marcos 10:43-44","explanation":"Diakonos (servo de mesa) e doulos (escravo voluntário). O maior no Reino é aquele que se inclina para lavar os pés dos outros.","illustration":"Jesus cingindo-se com uma toalha e lavando a poeira e o cansaço dos pés dos Seus discípulos.","application":"Procure oportunidades práticas de servir aos que ninguém repara na igreja e na comunidade.","orderIndex":1},{"id":"b81","title":"3. O Filho do Homem Veio Para Servir e Dar a Vida","biblicalReference":"Marcos 10:45","explanation":"O padrão definitivo: dar a própria vida em resgate de muitos. Liderança bíblica é marcada por amor sacrificial.","illustration":"O capitão que no naufrágio ajuda todos a entrarem nos botes salva-vidas antes de pensar em si mesmo.","application":"Lidere pelo exemplo vivo de abnegação, graça e generosidade.","orderIndex":2}],"conclusion":"A autoridade espiritual genuína não é imposta pelo grito ou pelo cargo; ela é conquistada pelo amor e serviço voluntário.","appeal":"Peça um coração de servo como o de Cristo para liderar com sabedoria e pureza."}'::jsonb
  ),
  (
    'Jovens Fortes no Poder da Palavra',
    'Pureza, Força Espiritual e Propósito no Século XXI',
    '1 João 2:14; 1 Timóteo 4:12',
    'Temático',
    ARRAY['Jovens', 'Pureza', 'Palavra', 'Vitória']::TEXT[],
    '{"introduction":"A juventude cristã não é o futuro da igreja; é o presente vibrante de Deus para confrontar a escuridão moral desta geração.","blocks":[{"id":"b82","title":"1. Jovens Sois Fortes Porque a Palavra Habita em Vós","biblicalReference":"1 João 2:14c","explanation":"A verdadeira força do jovem não está nos músculos ou juventude física, mas na Palavra de Deus enraizada no coração.","illustration":"A espada afiada guardada na bainha pronta para ser desembainhada contra as mentiras do inimigo.","application":"Dedique tempo diário à meditação bíblica e alimente sua mente com a verdade eterna.","orderIndex":0},{"id":"b83","title":"2. E Já Vencestes o Maligno","biblicalReference":"1 João 2:14d","explanation":"A vitória sobre as armadilhas da imoralidade, pornografia e relativismo já foi conquistada por Cristo na cruz e é nossa pela fé.","illustration":"José fugindo da mulher de Potifar: ele preferiu perder a capa do que perder a integridade diante de Deus.","application":"Fuja das paixões da mocidade e guarde a pureza dos seus olhos e pensamentos.","orderIndex":1},{"id":"b84","title":"3. Sê o Exemplo dos Fiéis na Palavra e no Amor","biblicalReference":"1 Timóteo 4:12","explanation":"Ninguém despreze a tua mocidade; pelo contrário, sê o padrão dos crentes no procedimento, amor, fé e pureza.","illustration":"Uma lamparina acesa no meio de uma caverna escura: não importa o tamanho da chama, ela dissipa as trevas ao redor.","application":"Assuma seu testemunho cristão com orgulho santo diante de seus colegas de escola ou faculdade.","orderIndex":2}],"conclusion":"Deus procura jovens dispostos a nadar contra a correnteza do mundo para manifestar o Reino de Deus.","appeal":"Consagre a sua juventude e os seus dons no altar do Senhor Jesus."}'::jsonb
  ),
  (
    'Aviva a Tua Obra no Meio dos Anos',
    'Quebrantamento, Arrependimento e o Retorno do Fogo Divino',
    'Habacuque 3:2; Salmo 85:6',
    'Temático',
    ARRAY['Avivamento', 'Oração', 'Fogo', 'Espírito Santo']::TEXT[],
    '{"introduction":"O avivamento bíblico não é mero barulho emocional passageiro; é a visitação soberana de Deus que gera arrependimento profundo e sede pela Sua glória.","blocks":[{"id":"b85","title":"1. O Reconhecimento da Frieza Espiritual","biblicalReference":"Habacuque 3:2a","explanation":"Ouvi, Senhor, a tua palavra e temi. Aviva a tua obra no meio dos anos. Quando a rotina fria toma conta da igreja, o clamor se torna urgente.","illustration":"As brasas de uma lareira que vão se cobrindo de cinzas cinzentas e precisam ser sopradas pelo vento.","application":"Examine seu coração com sinceridade: seu amor pelo Senhor continua tão ardente quanto nos primeiros dias?","orderIndex":0},{"id":"b86","title":"2. Na Tua Ira, Lembra-Te da Misericórdia","biblicalReference":"Habacuque 3:2b","explanation":"O avivamento nasce no leito do quebrantamento e da confissão sincera de pecados, nunca na presunção de santidade humana.","illustration":"A chuva torrencial que cai sobre a terra árida e rachada, fazendo brotar sementes adormecidas.","application":"Dobre seus joelhos em choro e confissão pelas omissões e desvios morais da nossa geração.","orderIndex":1},{"id":"b87","title":"3. O Retorno da Alegria da Salvação no Meio do Povo","biblicalReference":"Salmo 85:6","explanation":"Porventura não tornarás a vivificar-nos, para que o teu povo se alegre em ti? O fruto do avivamento é gozo incontido no Senhor.","illustration":"O povo de Israel no Pentecostes com línguas de fogo e uma ousadia que transformou milhares de vidas em um único dia.","application":"Clame por um derramamento fresco do Espírito Santo que renove sua paixão por almas e pela presença de Deus.","orderIndex":2}],"conclusion":"O avivamento começa quando um homem ou uma mulher decide parar de fingir e se entrega totalmente a Deus.","appeal":"Venha buscar o fogo purificador do Espírito Santo para a sua vida e para a sua igreja."}'::jsonb
  ),
  (
    'O Perdão que Destranca as Prisões da Alma',
    'Cura Emocional, Reconciliação e a Liberdade da Graça',
    'Mateus 18:21-35',
    'Temático',
    ARRAY['Perdão', 'Cura', 'Graça', 'Reconciliação']::TEXT[],
    '{"introduction":"Pedro perguntou a Jesus se perdoar sete vezes ao dia era suficiente; a resposta de Jesus revolucionou o conceito de perdão para sempre.","blocks":[{"id":"b88","title":"1. A Dívida Incalculável Perdoada pelo Rei","biblicalReference":"Mateus 18:23-27","explanation":"Dez mil talentos representavam séculos de trabalho de um servo comum. Deus nos perdoou uma dívida impagável pelo sangue de Cristo.","illustration":"Uma nota promissória bilionária rasgada e jogada no fogo sem cobrar um único centavo.","application":"Lembre-se do tamanho do perdão que você recebeu de Deus antes de cobrar as ofensas alheias.","orderIndex":0},{"id":"b89","title":"2. O Absurdo da Dureza de Coração com o Conservo","biblicalReference":"Mateus 18:28-30","explanation":"O servo perdoado agarrou pelo pescoço o colega que lhe devia cem denários. Guardar rancor é a maior ingratidão contra a cruz.","illustration":"Tomar veneno esperando que a outra pessoa morra: é exatamente o que a amargura faz com quem não perdoa.","application":"Abra a mão que quer esganar o seu ofensor e solte o fardo pesado do ressentimento.","orderIndex":1},{"id":"b90","title":"3. A Prisão Espiritual dos Atormentadores","biblicalReference":"Mateus 18:34-35","explanation":"Quem não perdoa do coração ao seu irmão é entregue aos verdugos emocionais: insônia, depressão, amargura e orações bloqueadas.","illustration":"A chave enferrujada da cela que o próprio prisioneiro carrega no bolso sem usar para se libertar.","application":"Use a chave do perdão voluntário hoje para abrir as portas da sua liberdade espiritual e física.","orderIndex":2}],"conclusion":"Perdoar não é dizer que o erro foi certo; é dizer que a dívida foi transferida para as mãos do Justo Juiz.","appeal":"Decida perdoar agora mesmo aquela pessoa que feriu o seu coração no passado."}'::jsonb
  ),
  (
    'Adoradores em Espírito e em Verdade',
    'A Adoração que o Pai Procura e a Cura da Falsa Religião',
    'João 4:23-24',
    'Temático',
    ARRAY['Adoração', 'Espírito', 'Verdade', 'Intimidade']::TEXT[],
    '{"introduction":"Junto ao poço de Jacó, Jesus revela à mulher samaritana o maior segredo sobre o louvor que agrada ao coração do Altíssimo.","blocks":[{"id":"b91","title":"1. A Superação dos Lugares Geográficos e Liturgias Mortas","biblicalReference":"João 4:21-22","explanation":"Nem no monte Gerizim nem em Jerusalém. A verdadeira adoração não está presa a catedrais suntuosas ou rituais externos vazios.","illustration":"O templo de pedra versus o templo vivo do corpo humano habitado pelo Espírito Santo.","application":"Não limite seu louvor ao culto de domingo; adore a Deus no trânsito, na cozinha e no trabalho.","orderIndex":0},{"id":"b92","title":"2. Os Adoradores que o Pai Procura Ativamente","biblicalReference":"João 4:23","explanation":"Deus não procura adoração bonita; Ele procura adoradores cuja motivação seja amar a Sua pessoa e santidade.","illustration":"O pai amoroso que procura o abraço carinhoso do filho no final do dia, e não presentes caros comprados.","application":"Apresente-se diante de Deus com simplicidade e verdade, despido de qualquer pose religiosa.","orderIndex":1},{"id":"b93","title":"3. Em Espírito e em Verdade: Alinhamento Integral","biblicalReference":"João 4:24","explanation":"Em espírito (com paixão, sinceridade interior e sob o mover do Espírito Santo) e em verdade (fundamentado na sã doutrina da Palavra).","illustration":"As duas asas de uma aeronave: entusiasmo sem doutrina vira heresia; doutrina sem fogo vira museu frio.","application":"Una o fervor do coração ao conhecimento bíblico para oferecer adoração excelente ao Rei.","orderIndex":2}],"conclusion":"Adorar não é cantar hinos bonitos; é viver de tal maneira que nossa vida inteira exale o aroma suave de Cristo.","appeal":"Entregue a sua adoração sincera ao Senhor hoje em espírito e em verdade."}'::jsonb
  ),
  (
    'A Verdadeira Riqueza do Contentamento',
    'Vencendo a Ditadura do Consumismo e a Ansiedade Material',
    '1 Timóteo 6:6-10; Filipenses 4:11-13',
    'Temático',
    ARRAY['Contentamento', 'Finanças', 'Simplicidade', 'Paz']::TEXT[],
    '{"introduction":"Em um mundo que bombardeia nossa mente dizendo que só seremos felizes se comprarmos mais, a Bíblia ensina o segredo do contentamento.","blocks":[{"id":"b94","title":"1. Grande Fonte de Lucro: Piedade com Contentamento","biblicalReference":"1 Timóteo 6:6-8","explanation":"Nada trouxemos para este mundo e dele nada podemos levar. Tendo o que comer e com que vestir, estejamos com isso satisfeitos.","illustration":"A bagagem de viagem de quem sabe que está apenas passando algumas noites num hotel antes de ir para a mansão eterna.","application":"Agradeça a Deus pelo teto, alimento e família que você tem hoje em vez de murmurar pelo que não possui.","orderIndex":0},{"id":"b95","title":"2. As Armadilhas e Dores dos que Querem Ficar Ricos a Todo Custo","biblicalReference":"1 Timóteo 6:9-10","explanation":"O amor ao dinheiro é a raiz de todos os males. Quem é dominado por essa ambição fura a própria alma com muitas dores e laços.","illustration":"O peixe que morde o anzol atraído pela isca reluzente e perde a própria vida na armadilha.","application":"Não sacrifique seu casamento, saúde e comunhão com Deus para acumular bens perecíveis.","orderIndex":1},{"id":"b96","title":"3. O Segredo de Paulo: Posso Todas as Coisas Naquele que Me Fortalece","biblicalReference":"Filipenses 4:11-13","explanation":"Aprendi a viver contente em toda e qualquer situação: na fartura ou na escassez. Minha força vem da comunhão com Cristo.","illustration":"A âncora fincada no fundo rochoso: o barco balança na maré alta e na maré baixa, mas não sai do lugar seguro.","application":"Encontre em Jesus a sua verdadeira riqueza e viva com o coração em paz.","orderIndex":2}],"conclusion":"Rico não é quem mais tem, mas quem menos precisa para ser plenamente grato e feliz no Senhor.","appeal":"Descanse na provisão divina e receba o refrigério do contentamento bíblico."}'::jsonb
  ),
  (
    'Quando o Profeta Entra na Caverna',
    'Como Deus Restaura a Alma do Desânimo, Exaustão e Solidão',
    '1 Reis 19:1-18',
    'Temático',
    ARRAY['Exaustão', 'Depressão', 'Restauração', 'Cuidado']::TEXT[],
    '{"introduction":"Após o grande triunfo no Monte Carmelo, o profeta Elias entra em profunda exaustão física e emocional e pede para morrer debaixo de um zimbro.","blocks":[{"id":"b97","title":"1. O Impacto da Exaustão Física e a Síndrome do Esgotamento","biblicalReference":"1 Reis 19:1-4","explanation":"Elias correu quilômetros, jejuou, enfrentou perseguição violenta. Homens de Deus são vulneráveis ao esgotamento físico e mental.","illustration":"A bateria descarregada: não adianta forçar a partida; o motor precisa de recarga na fonte de energia.","application":"Não se sinta culpado se você estiver cansado; reconheça seus limites humanos e busque descanso.","orderIndex":0},{"id":"b98","title":"2. O Cuidado Terapêutico e Sobrenatural do Anjo","biblicalReference":"1 Reis 19:5-8","explanation":"Deus não deu uma bronca teológica em Elias; enviou um anjo com pão quentinho e água fresca e mandou-o dormir de novo.","illustration":"A mãe amorosa que coloca a sopa quente na mesa e cobre o filho febril com cobertor limpo.","application":"Cuide da sua saúde física, alimentação e sono: seu corpo é templo do Espírito Santo.","orderIndex":1},{"id":"b99","title":"3. O Cicio Suave e a Nova Missão Fora da Caverna","biblicalReference":"1 Reis 19:11-18","explanation":"Deus não estava no terremoto nem no fogo impetuoso, mas no sopro de uma brisa suave. ''Que fazes aqui, Elias? Sai da caverna!''.","illustration":"A brisa matinal que limpa a neblina e traz a luz dourada do sol para mostrar o novo caminho a seguir.","application":"Ouça a voz calma de Deus chamando você para sair do isolamento: ainda há muitos projetos e companheiros esperando por você.","orderIndex":2}],"conclusion":"Deus nunca desiste dos Seus profetas quando eles entram em cavernas; Ele vai até lá para trazê-los de volta à luz.","appeal":"Saia da caverna do desânimo nesta noite e receba novo sopro de vida do Senhor."}'::jsonb
  ),
  (
    'Revestidos do Poder do Alto',
    'O Batismo no Espírito Santo e a Ousadia Para Testemunhar',
    'Atos 1:8; 2:1-4',
    'Temático',
    ARRAY['Espírito Santo', 'Pentecostes', 'Poder', 'Ousadia']::TEXT[],
    '{"introduction":"A promessa do Pai não é um adorno opcional para a igreja, mas a força motriz indispensável para cumprir a missão de Deus.","blocks":[{"id":"b100","title":"1. O Mandamento da Espera em Oração Unânime","biblicalReference":"Atos 1:4-5, 14","explanation":"Não saiam de Jerusalém até que do alto sejais revestidos de poder. Cento e vinte discípulos oravam perseverantemente no cenáculo.","illustration":"As velas do barco erguidas aguardando a chegada do vento forte para navegar mar adentro.","application":"Busque a presença do Espírito Santo com perseverança e sede contínua em suas orações.","orderIndex":0},{"id":"b101","title":"2. Mas Recebereis Poder (Dunamis)","biblicalReference":"Atos 1:8","explanation":"Dunamis: poder miraculoso e dinâmico para vencer o pecado e testemunhar com autoridade em todas as esferas da sociedade.","illustration":"A usina hidroelétrica que acende a iluminação de cidades inteiras através da força das águas volumosas.","application":"Deixe a timidez de lado e permita que a ousadia do Espírito transforme suas palavras em instrumentos de salvação.","orderIndex":1},{"id":"b102","title":"3. O Vento Impetuoso e as Línguas de Fogo","biblicalReference":"Atos 2:1-4","explanation":"Todos foram cheios do Espírito Santo e começaram a falar em outras línguas conforme o Espírito concedia. Fogo purificador e capacitador.","illustration":"O ferro que entra frio e escuro na fornalha e sai incandescente e moldável pelo ferreiro.","application":"Abra o seu coração para ser batizado e renovado pelo fogo consumidor do Espírito Santo.","orderIndex":2}],"conclusion":"A igreja não depende de oratória humana ou tecnologia para prevalecer, mas do sopro vivo do Espírito de Deus.","appeal":"Levante as mãos e peça o batismo e renovo do Espírito Santo agora mesmo."}'::jsonb
  ),
  (
    'O Evangelho em Uma Única Frase',
    'Deus, o Amor, a Dádiva, a Fé e a Vida Eterna',
    'João 3:16',
    'Textual',
    ARRAY['Evangelismo', 'Amor de Deus', 'Salvação', 'Cruz']::TEXT[],
    '{"introduction":"Considerado a Bíblia em miniatura, Martinho Lutero chamou João 3:16 do resumo mais sublime de toda a revelação divina.","blocks":[{"id":"b103","title":"1. A Fonte Suprema: Porque Deus Amou o Mundo de Tal Maneira","biblicalReference":"João 3:16a","explanation":"A iniciativa da salvação não partiu do homem, mas do amor soberano, imensurável e sacrificial de Deus pela humanidade caída.","illustration":"O oceano que não cabe em um copo de água: a mente finita jamais esgotará as profundezas do amor divino.","application":"Nunca duvide do valor que você tem diante de Deus; Ele amou você a ponto de dar Seu Filho unigênito.","orderIndex":0},{"id":"b104","title":"2. A Dádiva Incomparável: Que Deu o Seu Filho Unigênito","biblicalReference":"João 3:16b","explanation":"Deus não enviou um anjo ou um profeta; Ele entregou Seu próprio Filho amado para morrer a nossa morte na cruz.","illustration":"O pai que se atira nas chamas ardentes da casa para resgatar o filho preso no quarto.","application":"Receba o sacrifício de Jesus como o único e suficiente preço pago pela sua reconciliação com o Criador.","orderIndex":1},{"id":"b105","title":"3. A Condição Simples e a Promessa Eterna: Crer e Ter a Vida Eterna","biblicalReference":"João 3:16c","explanation":"Para que todo aquele que nele crê não pereça, mas tenha a vida eterna. Não é mérito por obras, é fé no Redentor.","illustration":"A mão vazia do mendigo estendida para receber um presente inestimável que ele jamais poderia comprar.","application":"Deposite sua confiança total em Jesus hoje e tome posse da vida eterna que nunca acabará.","orderIndex":2}],"conclusion":"Em uma única frase, Jesus resumiu a maior história de amor e redenção do universo.","appeal":"Entregue o seu coração a Jesus e receba agora o dom gratuito da salvação."}'::jsonb
  ),
  (
    'A Árvore Plantada Junto às Águas',
    'A Bem-Aventurança da Delícia na Palavra do Senhor',
    'Salmo 1:1-3',
    'Textual',
    ARRAY['Palavra', 'Salmos', 'Fruto', 'Prosperidade Bíblica']::TEXT[],
    '{"introduction":"O Salmo 1 abre o saltério traçando a nítida bifurcação entre dois caminhos: a vida fecunda do justo e o fim estéril dos ímpios.","blocks":[{"id":"b106","title":"1. As Três Renúncias do Homem Bem-Aventurado","biblicalReference":"Salmo 1:1","explanation":"Não anda no conselho dos ímpios, não se detém no caminho dos pecadores, não se assenta na roda dos escarnecedores. A marcha regressiva do pecado.","illustration":"O pedestre que primeiro caminha com más companhias, depois para para conversar e finalmente senta-se no mesmo banco que eles.","application":"Cuidado com quem você consulta para tomar conselhos financeiros, éticos e matrimoniais.","orderIndex":0},{"id":"b107","title":"2. O Prazer Incessante na Lei do Senhor","biblicalReference":"Salmo 1:2","explanation":"Antes o seu prazer está na lei do Senhor, e na sua lei medita de dia e de noite. Não é obrigação fardo, é delícia e alimento para a alma.","illustration":"A abelha que se deleita em pousar nas flores perfumadas para produzir o mel mais puro da colmeia.","application":"Torne a leitura bíblica diária o momento mais esperado e saboroso da sua rotina.","orderIndex":1},{"id":"b108","title":"3. A Árvore Frutífera e a Prosperidade que Permanece","biblicalReference":"Salmo 1:3","explanation":"Será como a árvore plantada junto a ribeiros de águas: dá fruto na estação própria, folhagem não murcha e tudo o que faz prospera.","illustration":"A tamareira do deserto cujas raízes descem metros até encontrar o lençol freático secreto sob a areia quente.","application":"Aprofunde suas raízes em Deus para continuar dando frutos mesmo nos invernos e secas da vida.","orderIndex":2}],"conclusion":"Quem tem suas raízes nutridas pela Palavra de Deus nunca seca nem perde o vigor da sua fé.","appeal":"Faça da Bíblia a sua bússola diária e experimente a verdadeira fertilidade espiritual."}'::jsonb
  ),
  (
    'Pensamentos de Paz e um Futuro Esperançoso',
    'O Soberano e Gracioso Plano de Deus Para a Nossa Vida',
    'Jeremias 29:11-13',
    'Textual',
    ARRAY['Esperança', 'Futuro', 'Planos de Deus', 'Oração']::TEXT[],
    '{"introduction":"Enviada aos exilados que choravam escravizados na Babilônia, esta carta profética revela o coração paternal do Todo-Poderoso.","blocks":[{"id":"b109","title":"1. A Certeza dos Desígnios Divinos: Eu Sei os Pensamentos","biblicalReference":"Jeremias 29:11a","explanation":"Eu bem sei os pensamentos que penso de vós, diz o Senhor. Deus não improvisa o nosso destino; Ele tem propósitos eternos e perfeitos.","illustration":"O arquiteto que vê a maquete e o prédio pronto com toda a segurança antes mesmo de colocar o primeiro tijolo.","application":"Descanse na certeza de que sua vida não está à mercê do acaso ou da sorte, mas nas mãos do Pai.","orderIndex":0},{"id":"b110","title":"2. A Natureza dos Planos: Pensamentos de Paz e Não de Mal","biblicalReference":"Jeremias 29:11b","explanation":"Shalom: paz completa, inteireza, harmonia e salvação para vos dar um fim e uma esperança viva no amanhã.","illustration":"O cirurgião que fere o paciente com o bisturi não para destruir, mas para extrair o tumor e salvar a vida.","application":"Entenda que mesmo os momentos difíceis são instrumentos pedagógicos de Deus para um futuro abençoado.","orderIndex":1},{"id":"b111","title":"3. A Busca com Todo o Coração e a Promessa de Encontro","biblicalReference":"Jeremias 29:12-13","explanation":"Então me invocareis, passareis a orar a mim e eu vos ouvirei. Buscar-me-eis e me achareis quando me buscardes de todo o coração.","illustration":"O filho pequeno que procura o abraço do pai com lágrimas nos olhos e é imediatamente envolvido pelo amor protetor.","application":"Busque a presença de Deus com intensidade e paixão total, sem reservas ou fingimentos.","orderIndex":2}],"conclusion":"Deus tem um amanhã de esperança reservado para você: não olhe para trás, olhe para os planos dEle.","appeal":"Entregue o controle do seu futuro ao Senhor e receba a paz que vem do céu."}'::jsonb
  ),
  (
    'O que o Senhor Requer de Ti',
    'Justiça, Misericórdia e Humildade Diante do Criador',
    'Miqueias 6:8',
    'Textual',
    ARRAY['Justiça', 'Misericórdia', 'Humildade', 'Vida Cristã']::TEXT[],
    '{"introduction":"Em meio a uma religiosidade externa cheia de sacrifícios de animais mas vazia de ética, o profeta resume a essência do que Deus espera de nós.","blocks":[{"id":"b112","title":"1. Ele Te Declarou, Ó Homem, o que É Bom","biblicalReference":"Miqueias 6:8a","explanation":"Deus não esconde Sua vontade em mistérios indecifráveis; Ele já revelou com clareza cristalina na Sua Palavra o padrão excelente de vida.","illustration":"O mapa nítido entregue nas mãos do viajante antes de iniciar a travessia pela floresta densa.","application":"Pare de inventar desculpas para a desobediência e alinhe seus passos à vontade expressa de Deus.","orderIndex":0},{"id":"b113","title":"2. Praticar a Justiça e Amar a Misericórdia (Hesed)","biblicalReference":"Miqueias 6:8b","explanation":"Justiça nas relações sociais e financeiras diárias; amor leal (hesed), compaixão e graça para com os necessitados e ofensores.","illustration":"Os dois braços da balança: retidão ética de um lado e compaixão generosa do outro.","application":"Seja honesto nos seus negócios e estenda a mão para socorrer quem não tem nada para te oferecer em troca.","orderIndex":1},{"id":"b114","title":"3. Andar Humildemente com o Teu Deus","biblicalReference":"Miqueias 6:8c","explanation":"Reconhecer que somos pequenos e dependentes; caminhar em submissão diária lado a lado com o Pai celestial sem soberba.","illustration":"A criança que segura a mão forte do pai ao atravessar a avenida movimentada da cidade.","application":"Renuncie à autossuficiência e aprenda a depender do Senhor em todas as decisões do seu dia.","orderIndex":2}],"conclusion":"Deus não quer rituais vazios nem aparências religiosas; Ele quer corações justos, misericordiosos e humildes.","appeal":"Ajuste o seu coração à simplicidade e profundidade do que o Senhor pede de você."}'::jsonb
  ),
  (
    'As Quatro Condições Para a Cura da Terra',
    'O Caminho do Arrependimento e a Promessa do Avivamento',
    '2 Crônicas 7:14',
    'Textual',
    ARRAY['Oração', 'Arrependimento', 'Cura', 'Avivamento']::TEXT[],
    '{"introduction":"Na dedicação solene do Templo de Salomão, Deus desce em fogo e deixa a chave mestre para a restauração de um povo em crise.","blocks":[{"id":"b115","title":"1. O Povo que se Chama Pelo Meu Nome se Humilhar e Orar","biblicalReference":"2 Crônicas 7:14a","explanation":"A responsabilidade pela crise moral não começa no governo mundano, mas na igreja. Humilhação voluntária e oração insistente.","illustration":"O doente que finalmente para de fingir saúde e corre aos pés do médico especialista pedindo socorro.","application":"Dobre seus joelhos com humildade genuína e clame pela sua família e por sua nação.","orderIndex":0},{"id":"b116","title":"2. Buscar a Minha Face e Converter-se dos Maus Caminhos","biblicalReference":"2 Crônicas 7:14b","explanation":"Buscar a face (intimidade) e não apenas as mãos (bênçãos). Arrependimento genuíno exige mudança radical de direção de 180 graus.","illustration":"O motorista que percebe estar na contramão da rodovia e faz o retorno imediatamente para evitar a tragédia.","application":"Abandone hoje aquele pecado de estimação que tem roubado a sua paz com Deus.","orderIndex":1},{"id":"b117","title":"3. A Tríplice Resposta do Céu: Ouvir, Perdoar e Sarar a Terra","biblicalReference":"2 Crônicas 7:14c","explanation":"Então Eu ouvirei dos céus, perdoarei os seus pecados e sararei a sua terra. Restauração espiritual, emocional e social completa.","illustration":"A terra seca e rachada pelo sol que recebe a chuva serôdia e floresce com abundância verdejante.","application":"Creia que a oração humilde da igreja tem poder para reverter qualquer crise política ou espiritual.","orderIndex":2}],"conclusion":"Se a igreja fizer o que cabe a ela de joelhos, Deus fará do céu aquilo que nenhum poder terreno é capaz de realizar.","appeal":"Coloque-se na brecha como intercessor pelo seu lar, igreja e cidade."}'::jsonb
  ),
  (
    'Confiança Total no Senhor',
    'Direção Divina e Renúncia ao Próprio Entendimento',
    'Provérbios 3:5-6',
    'Textual',
    ARRAY['Confiança', 'Direção', 'Sabedoria', 'Fé']::TEXT[],
    '{"introduction":"O livro de Provérbios nos ensina a arte de viver com sabedoria, colocando a bússola de nossa vida inteira nas mãos do Senhor.","blocks":[{"id":"b118","title":"1. Confia no Senhor de Todo o Teu Coração","biblicalReference":"Provérbios 3:5a","explanation":"Confiança sem meias palavras, sem reservas e sem planos alternativos secretos. O hebraico batach denota atirar-se de bruços sobre algo seguro.","illustration":"O paraquedista que salta do avião confiando plenamente que o tecido se abrirá no momento certo.","application":"Entregue suas preocupações mais íntimas ao cuidado de Deus sem guardar cartas na manga.","orderIndex":0},{"id":"b119","title":"2. Não Te Estribes no Teu Próprio Entendimento","biblicalReference":"Provérbios 3:5b","explanation":"Nossa lógica humana é limitada e muitas vezes míope. Apoiar-se na própria esperteza é construir sobre areia movediça.","illustration":"A bengala de bambu rachada que se rompe e fere a mão daquele que se apoia nela com força total.","application":"Consulte a Palavra de Deus antes de tomar decisões financeiras, relacionais ou de carreira.","orderIndex":1},{"id":"b120","title":"3. Reconhece-O em Todos os Teus Caminhos e Ele Endireitará Tuas Veredas","biblicalReference":"Provérbios 3:6","explanation":"Reconhecer a Deus não é dar um aceno formal de domingo, mas submeter cada passo diário ao senhorio dEle. Ele aplaina os montes e curvas.","illustration":"O trator que abre caminho reto através da mata virgem aplainando os buracos e pedras para o viajante passar.","application":"Ore antes de cada reunião e decisão cotidiana, permitindo que Deus lidere os seus passos.","orderIndex":2}],"conclusion":"Quem confia no Senhor nunca se perde no caminho, porque o próprio Deus guia os seus passos rumo à vitória.","appeal":"Abra mão do volante da sua vida e passe o controle para Jesus Cristo."}'::jsonb
  ),
  (
    'Ferido Pelas Nossas Transgressões',
    'O Sofrimento Substitutivo do Servo do Senhor no Calvário',
    'Isaías 53:4-5',
    'Textual',
    ARRAY['Cruz', 'Redenção', 'Cura', 'Sacrifício', 'Graça']::TEXT[],
    '{"introduction":"Setecentos anos antes do Calvário, o profeta Isaías descreve os detalhes impressionantes da crucificação como se estivesse aos pés da cruz.","blocks":[{"id":"b121","title":"1. Ele Tomou Sobre Si as Nossas Dores e Enfermidades","biblicalReference":"Isaías 53:4","explanation":"Verdadeiramente Ele tomou sobre Si as nossas enfermidades e as nossas dores levou sobre Si. A cruz é o lugar da substituição penal e graciosa.","illustration":"O homem inocente que se voluntaria para sentar no banco dos réus e assumir a sentença de morte no lugar do culpado.","application":"Entregue a Ele todo o peso da sua culpa e dor emocional: Ele já carregou tudo na cruz por você.","orderIndex":0},{"id":"b122","title":"2. O Castigo que Nos Traz a Paz Estava Sobre Ele","biblicalReference":"Isaías 53:5a","explanation":"Moído pelas nossas iniquidades e transpassado pelos nossos pecados. A ira santa de Deus contra o pecado recaiu inteiramente sobre o Filho.","illustration":"O para-raios que atrai o raio fulminante do céu protegendo a casa inteira da destruição.","application":"Viva em paz com Deus hoje sabendo que a sua dívida foi plenamente quitada no sangue de Jesus.","orderIndex":1},{"id":"b123","title":"3. Pelas Suas Pisaduras Fomos Sarados","biblicalReference":"Isaías 53:5b","explanation":"As feridas físicas e espirituais de Cristo na cruz tornaram-se o bálsamo eterno que cura a lepra da nossa alma e nos devolve a vida.","illustration":"O antídoto extraído do próprio veneno da serpente que cura a vítima picada à beira da morte.","application":"Tome posse da cura espiritual e da restauração que fluem das feridas santas do Redentor.","orderIndex":2}],"conclusion":"Na cruz não houve acidente histórico; houve o maior ato de amor e redenção voluntária da história do universo.","appeal":"Ajoelhe-se aos pés da cruz e receba a salvação e a paz que Jesus conquistou para você."}'::jsonb
  ),
  (
    'A Prioridade Inegociável do Reino',
    'Buscando Primeiro o Reino e Vencendo a Ansiedade do Amanhã',
    'Mateus 6:33',
    'Textual',
    ARRAY['Reino de Deus', 'Prioridades', 'Provisão', 'Descanso']::TEXT[],
    '{"introduction":"Em meio às ansiedades cotidianas por comida, bebida e roupas, Jesus estabelece a ordem prioritária que destranca as bênçãos celestiais.","blocks":[{"id":"b124","title":"1. O Imperativo da Ordem: Buscai em Primeiro Lugar","biblicalReference":"Mateus 6:33a","explanation":"Proton (primeiro em tempo, prioridade e valor). Deus não aceita o segundo lugar nem as sobras do nosso tempo, dinheiro ou energia.","illustration":"O botão superior da camisa: se você abotoar o primeiro botão na casa errada, todos os outros ficarão tortos até o final.","application":"Coloque Deus no início do seu dia, na primazia das suas finanças e no topo da sua agenda familiar.","orderIndex":0},{"id":"b125","title":"2. O Alvo da Busca: O Seu Reino e a Sua Justiça","biblicalReference":"Mateus 6:33b","explanation":"O Reino é o governo soberano de Deus em nossa vida; Sua justiça é o padrão moral de integridade e obediência à Sua Palavra.","illustration":"O súdito leal que busca expandir a honra do seu Rei em todas as cidades por onde passa.","application":"Viva de tal maneira que a glória de Deus e a salvação de almas sejam a principal paixão do seu coração.","orderIndex":1},{"id":"b126","title":"3. A Promessa Fiel: Todas Estas Coisas Vos Serão Acrescentadas","biblicalReference":"Mateus 6:33c","explanation":"Provisão material não é o alvo da corrida do crente; é o acréscimo gracioso que o Pai providencia para quem cuida das coisas do Reino.","illustration":"O pai que compra o material escolar e os alimentos para o filho dedicado que foca em estudar com amor.","application":"Pare de viver estressado pelo pão de amanhã; foque em agradar a Deus e veja as portas se abrirem.","orderIndex":2}],"conclusion":"Quando cuidamos dos negócios de Deus na terra, Ele cuida com fidelidade de todos os nossos negócios pessoais.","appeal":"Reorganize sua lista de prioridades hoje e coloque o Reino de Deus em primeiro lugar."}'::jsonb
  ),
  (
    'O Culto Racional e a Mente Renovada',
    'Não Vos Conformeis com Este Século, Mas Transformai-vos',
    'Romanos 12:1-2',
    'Textual',
    ARRAY['Consagração', 'Mente', 'Vontade de Deus', 'Santidade']::TEXT[],
    '{"introduction":"Após expor 11 capítulos sobre as misericórdias de Deus na salvação, Paulo faz o apelo prático mais urgente para a vida do cristão.","blocks":[{"id":"b127","title":"1. O Corpo Como Sacrifício Vivo, Santo e Agradável a Deus","biblicalReference":"Romanos 12:1","explanation":"No Antigo Testamento o sacrifício era morto; em Cristo nós somos sacrifícios vivos. Este é o vosso culto racional (logike latreia).","illustration":"O fogo do altar de Deus que consome a lenha da oferta voluntária sem deixar cinzas para o mundo.","application":"Consagre seus olhos, mãos, pés e sexualidade como instrumentos diários de santidade ao Senhor.","orderIndex":0},{"id":"b128","title":"2. Não Vos Conformeis com Este Século","biblicalReference":"Romanos 12:2a","explanation":"Suschematizo: não se amolde à forma exterior dos valores caídos deste mundo. O mundo quer colocar você na sua própria fôrma moral.","illustration":"A massa de gesso maleável que assume o formato de qualquer fôrma plástica onde é despejada.","application":"Tenha coragem santa de dizer ''não'' aos padrões mundanos de desonestidade, impureza e relativismo.","orderIndex":1},{"id":"b129","title":"3. A Metamorfose Mental e a Vontade Boa, Agradável e Perfeita","biblicalReference":"Romanos 12:2b","explanation":"Metamorphoo: transformação de dentro para fora pela renovação contínua da mente pela Palavra de Deus.","illustration":"A lagarta feia e rastejante que entra no casulo e ressurge como uma borboleta livre voando nas alturas celestiais.","application":"Alimente seus pensamentos com a Bíblia para experimentar a perfeita, boa e agradável vontade do Pai.","orderIndex":2}],"conclusion":"A verdadeira adoração não dura apenas duas horas no domingo; ela envolve nosso corpo e nossa mente a cada minuto do dia.","appeal":"Entregue todo o seu ser no altar de Deus como um sacrifício vivo e consagrado."}'::jsonb
  ),
  (
    'Sê Forte e Corajoso no Poder da Promessa',
    'Superando o Medo pela Convicção da Presença Divina',
    'Josué 1:9',
    'Textual',
    ARRAY['Coragem', 'Presença de Deus', 'Conquista', 'Fé']::TEXT[],
    '{"introduction":"Com a morte de Moisés e o rio Jordão intransponível à frente, o jovem Josué recebe o imperativo de fé que ecoa até os nossos dias.","blocks":[{"id":"b130","title":"1. O Mandamento Soberano: Não to Mandei Eu?","biblicalReference":"Josué 1:9a","explanation":"A ordem não partiu de homens; partiu do Rei do universo. Se Deus mandou, Ele garante o suporte, a provisão e a vitória final.","illustration":"O soldado que recebe a ordem direta do general: ele não vacila nem duvida do êxito da missão confiada.","application":"Não tema os desafios que estão diante de você se você estiver no centro da vontade de Deus.","orderIndex":0},{"id":"b131","title":"2. A Postura da Fé: Sê Forte, Corajoso, Não Temas Nem Te Espantes","biblicalReference":"Josué 1:9b","explanation":"Coragem não é ausência de medo, mas a decisão santa de avançar apesar dos gigantes e muralhas ameaçadoras.","illustration":"Davi avançando contra Golias: pequeno no porte físico, mas gigante na confiança no Deus dos exércitos de Israel.","application":"Dê o passo de fé e pise nas águas do seu Jordão crendo que Deus abrirá o caminho à sua frente.","orderIndex":1},{"id":"b132","title":"3. O Combustível da Ousadia: O Senhor Teu Deus É Contigo","biblicalReference":"Josué 1:9c","explanation":"O Senhor teu Deus é contigo por onde quer que andares. A presença de Deus dissipa a solidão e anula o poder dos inimigos.","illustration":"O filho pequeno que caminha destemido no bosque escuro porque está de mãos dadas com o pai amoroso.","application":"Tome posse da promessa: onde você colocar a planta dos seus pés, a presença do Senhor estará com você.","orderIndex":2}],"conclusion":"Nenhum obstáculo é grande demais quando marchamos debaixo da ordem e da presença infalível do Todo-Poderoso.","appeal":"Levante-se com coragem santa e tome posse das promessas que Deus tem para a sua vida."}'::jsonb
  ),
  (
    'No Esconderijo Seguro do Altíssimo',
    'A Habitação Íntima Sob a Sombra Protetora do Onipotente',
    'Salmo 91:1-2',
    'Textual',
    ARRAY['Proteção', 'Salmos', 'Refúgio', 'Intimidade']::TEXT[],
    '{"introduction":"O Salmo 91 é a mais célebre fortaleza poética das Escrituras, revelando que a segurança do crente depende de onde ele decide habitar.","blocks":[{"id":"b133","title":"1. Aquele que Habita no Esconderijo Secreto do Altíssimo","biblicalReference":"Salmo 91:1a","explanation":"Não diz ''aquele que visita de vez em quando'', mas aquele que habita, que faz da presença de Deus a sua residência permanente.","illustration":"A casa construída na rocha sólida contra as tempestades e enchentes devastadoras da serra.","application":"Mude-se hoje do endereço da ansiedade e da pressa para a morada permanente da oração e intimidade com Deus.","orderIndex":0},{"id":"b134","title":"2. À Sombra do Onipotente Descansará","biblicalReference":"Salmo 91:1b","explanation":"Shaddai: o Deus Todo-Suficiente. Estar à sombra de alguém exige estar extremamente perto desse alguém. Descanso sem aflição.","illustration":"O filhote de águia aninhado sob as asas quentes da mãe enquanto o granizo cai violentamente fora do ninho.","application":"Acalme o seu coração agitado: as asas protetoras de Deus estão estendidas sobre a sua casa.","orderIndex":1},{"id":"b135","title":"3. A Confissão Ousada da Fé: Meu Refúgio e Meu Deus em Quem Confio","biblicalReference":"Salmo 91:2","explanation":"Direi do Senhor: Ele é o meu refúgio e a minha fortaleza; o meu Deus, em quem confiarei. A fé precisa ser confessada com a boca.","illustration":"O soldado que corre para dentro da fortaleza de pedra e fecha o portão de ferro atrás de si.","application":"Declare em voz alta sobre seus filhos e sua saúde que o Senhor é o seu refúgio inabalável.","orderIndex":2}],"conclusion":"Quem reside no esconderijo do Altíssimo não teme espanto noturno nem seta que voe de dia.","appeal":"Faça da presença de Deus a sua morada definitiva nesta noite."}'::jsonb
  ),
  (
    'A Minha Graça Te Basta',
    'O Poder de Deus que se Aperfeiçoa na Fraqueza Humana',
    '2 Coríntios 12:9-10',
    'Textual',
    ARRAY['Graça', 'Fraqueza', 'Poder', 'Sofrimento']::TEXT[],
    '{"introduction":"Paulo orou três vezes para que Deus retirasse o espinho na carne; a resposta que ele recebeu do Senhor transformou para sempre a sua teologia de poder.","blocks":[{"id":"b136","title":"1. A Resposta Divina que Supera o Nosso Pedido","biblicalReference":"2 Coríntios 12:9a","explanation":"A minha graça te basta. Deus nem sempre remove a fornalha ou o espinho, mas sempre multiplica a graça para suportarmos e vencermos.","illustration":"O navio que navega em águas rasas com pedras perigosas: Deus não remove as pedras, mas eleva o nível da água para o navio flutuar por cima.","application":"Pare de exigir que Deus mude as circunstâncias antes de pedir que Ele encha o seu coração de graça.","orderIndex":0},{"id":"b137","title":"2. O Poder que se Aperfeiçoa na Fraqueza","biblicalReference":"2 Coríntios 12:9b","explanation":"Porque o poder se aperfeiçoa na fraqueza. Quando somos autossuficientes, Deus não pode operar; quando reconhecemos nossa fraqueza, a glória dEle brilha.","illustration":"A lâmpada de barro rachada: é pelas frestas das rachaduras que a luz interior brilha mais forte no escuro.","application":"Não se envergonhe de suas limitações; elas são o palco perfeito para o agir milagroso de Deus.","orderIndex":1},{"id":"b138","title":"3. O Paradoxo Glorioso: Quando Estou Fraco, Então Sou Forte","biblicalReference":"2 Coríntios 12:10","explanation":"Sinto prazer nas fraquezas, nas injúrias, nas necessidades por amor de Cristo; porque quando sou fraco, a força de Cristo habita em mim.","illustration":"A criança que não consegue abrir a tampa do pote de vidro e entrega nas mãos fortes do pai que abre num segundo.","application":"Apoie-se nos braços do Redentor e experimente a força que não provém de recursos humanos.","orderIndex":2}],"conclusion":"A graça de Deus não é um mero consolo poético; é a força onipotente de Cristo capacitando os Seus filhos mais frágeis.","appeal":"Receba a graça que basta para enfrentar os espinhos da sua vida com a cabeça erguida."}'::jsonb
  ),
  (
    'O Caminho, a Verdade e a Vida',
    'A Exclusividade e Plenitude de Jesus Cristo na Salvação',
    'João 14:6',
    'Textual',
    ARRAY['Cristologia', 'Salvação', 'Exclusividade', 'Caminho']::TEXT[],
    '{"introduction":"Em um mundo pluralista e relativista que afirma que todos os caminhos levam a Deus, Jesus faz a mais categórica declaração de toda a história humana.","blocks":[{"id":"b139","title":"1. Eu Sou o Caminho: A Ponte Única Sobre o Abismo do Pecado","biblicalReference":"João 14:6a","explanation":"Jesus não apenas aponta a direção como uma placa estática; Ele próprio é a via viva de acesso que nos conecta ao Pai celestial.","illustration":"A ponte de concreto sólido que atravessa o abismo intransponível ligando a terra condenada ao paraíso eterno.","application":"Não tente chegar a Deus por méritos próprios ou religiosidades vazias: venha unicamente através de Cristo.","orderIndex":0},{"id":"b140","title":"2. Eu Sou a Verdade: A Luz que Dissipa as Ilusões do Mundo","biblicalReference":"João 14:6b","explanation":"Aletheia: a verdade absoluta e imutável encarnada. Ele não veio ensinar uma filosofia; Ele é a própria verdade viva.","illustration":"O raio de sol que penetra a sala escura e expõe cada partícula de poeira e falsidade acumulada.","application":"Alinhe suas convicções morais e decisões diárias à verdade revelada por Jesus nos evangelhos.","orderIndex":1},{"id":"b141","title":"3. Eu Sou a Vida e a Entrada Exclusiva ao Pai","biblicalReference":"João 14:6c","explanation":"Ninguém vem ao Pai senão por Mim. Zoe: a vida eterna e abundante de Deus que vence a morte espiritual e física.","illustration":"A água pura que sacia a garganta ressequida do viajante prestes a morrer de desidratação no deserto.","application":"Tome posse da vida abundante que Jesus oferece hoje e celebre a comunhão direta com o Pai.","orderIndex":2}],"conclusion":"Jesus não é uma das opções no cardápio de religiões do mundo; Ele é o único Salvador, Senhor e Mediador eterno.","appeal":"Renda-se a Jesus como o seu único Caminho, sua Verdade e sua Vida nesta noite."}'::jsonb
  ),
  (
    'Eis que Estou à Porta e Bato',
    'O Convite Urgente da Intimidade e Comunhão com o Salvador',
    'Apocalipse 3:20',
    'Textual',
    ARRAY['Comunhão', 'Ceia', 'Intimidade', 'Apocalipse']::TEXT[],
    '{"introduction":"Escrita à igreja morna de Laodiceia, esta passagem apresenta a cena mais dramática da Bíblia: o Criador do universo batendo na porta do coração humano.","blocks":[{"id":"b142","title":"1. A Postura Paciente e Persistente do Senhor: Estou à Porta e Bato","biblicalReference":"Apocalipse 3:20a","explanation":"Jesus não arromba as portas do coração humano. Ele respeita nossa vontade e bate através da Palavra, dos acontecimentos e do Espírito Santo.","illustration":"A famosa pintura de Holman Hunt: a porta coberta de trepadeiras com a maçaneta apenas pelo lado de dentro.","application":"Reconheça a voz de Jesus chamando você agora mesmo no secreto do seu coração.","orderIndex":0},{"id":"b143","title":"2. A Condição Humana: Se Alguém Ouvir a Minha Voz e Abrir a Porta","biblicalReference":"Apocalipse 3:20b","explanation":"Ouvir a voz exige silenciar o barulho do mundo; abrir a porta exige a atitude corajosa de remover os trincos do orgulho.","illustration":"O anfitrião que escuta a batida suave na chuva e corre para destrancar a fechadura emperrada da casa.","application":"Abra todas as portas e gavetas da sua vida para Jesus entrar e fazer morada.","orderIndex":1},{"id":"b144","title":"3. A Promessa de Ceia Íntima e Comunhão Eterna","biblicalReference":"Apocalipse 3:20c","explanation":"Entrarei em sua casa e cearei com ele, e ele comigo. No oriente, cear juntos é o selo máximo de amizade profunda, paz e comunhão inegociável.","illustration":"A mesa iluminada onde o pão é partido entre amigos íntimos rindo e conversando pela noite adentro.","application":"Desfrute da comunhão diária com Jesus que transforma a solidão da alma em banquete espiritual.","orderIndex":2}],"conclusion":"O Rei da Glória está do lado de fora esperando que você gire a maçaneta do seu coração por dentro.","appeal":"Abra a porta da sua vida para Jesus agora mesmo e comece a cear com Ele."}'::jsonb
  ),
  (
    'Deus É Nosso Refúgio e Fortaleza',
    'Paz, Socorro Bem Presente e Quietude em Meio ao Caos',
    'Salmo 46:1-3, 10',
    'Textual',
    ARRAY['Refúgio', 'Salmos', 'Paz', 'Soberania', 'Descanso']::TEXT[],
    '{"introduction":"O hino que inspirou Martinho Lutero a compor ''Castelo Forte'': quando as montanhas desmoronam no mar, o povo de Deus permanece inabalável.","blocks":[{"id":"b145","title":"1. O Socorro Bem Presente na Hora da Angústia","biblicalReference":"Salmo 46:1","explanation":"Deus é o nosso refúgio (lugar seguro onde nos escondemos) e fortaleza (poder que nos capacita a resistir). Socorro imediato, não distante.","illustration":"A torre alta de pedra construída no topo do monte onde os camponeses se abrigavam durante os ataques inimigos.","application":"Corra para os braços de Deus antes de procurar refúgios falsos nas drogas, no álcool ou na fuga emocional.","orderIndex":0},{"id":"b146","title":"2. A Coragem Diante do Colapso da Criação","biblicalReference":"Salmo 46:2-3","explanation":"Pelo que não temeremos, ainda que a terra se mude e os montes se transportem para o meio dos mares. Fé que não depende da estabilidade terrena.","illustration":"O farol marítimo construído sobre a rocha: as ondas gigantescas quebram com fúria contra ele, mas sua lâmpada continua guiando os navios.","application":"Mantenha a serenidade mesmo quando notícias ruins abalarem a economia ou a estabilidade da sua família.","orderIndex":1},{"id":"b147","title":"3. O Mandamento Divino: Aquietai-vos e Sabei que Eu Sou Deus","biblicalReference":"Salmo 46:10","explanation":"Cessai as lutas inúteis; tirai as mãos; soltai o controle e reconhecei que o Soberano governa e será exaltado entre as nações.","illustration":"A criança assustada que para de se debater quando o pai a pega no colo e sussurra: ''Fica quietinha, o papai está aqui''.","application":"Aquiete a sua alma ansiosa hoje e deixe Deus ser Deus na condução da sua vida.","orderIndex":2}],"conclusion":"O Senhor dos Exércitos está conosco; o Deus de Jacó é o nosso refúgio inexpugnável.","appeal":"Aquiete o seu coração agora e descanse na soberania de Deus."}'::jsonb
  ),
  (
    'A Alegria do Senhor É a Vossa Força',
    'A Palavra que Restaura, Quebra a Tristeza e Gera Força Sobrenatural',
    'Neemias 8:10',
    'Textual',
    ARRAY['Alegria', 'Força', 'Palavra', 'Restauração']::TEXT[],
    '{"introduction":"Após a reconstrução dos muros de Jerusalém, Esdras lê a Palavra de Deus e o povo chora de quebrantamento; Neemias então proclama a festa da graça.","blocks":[{"id":"b148","title":"1. O Choro Curativo do Quebrantamento Diante da Lei","biblicalReference":"Neemias 8:9","explanation":"Todo o povo chorava ouvindo as palavras da Lei. As lágrimas da confissão sincera de pecados preparam o terreno para o adubo da graça.","illustration":"A chuva que lava a poeira das janelas antes de o sol reluzir com clareza límpida na sala de estar.","application":"Não esconda suas falhas diante de Deus; deixe o Espírito Santo trazer o choro curador do arrependimento.","orderIndex":0},{"id":"b149","title":"2. A Ordem da Celebração e da Partilha Generosa","biblicalReference":"Neemias 8:10a","explanation":"Ide, comei as carnes gordas, tomai as bebidas doces e enviai porções aos que nada têm preparado; porque este dia é consagrado ao Senhor.","illustration":"O banquete comunitário onde ninguém fica de fora e a generosidade espalha o amor de Deus aos mais vulneráveis.","application":"Compartilhe suas bênçãos materiais e espirituais com quem está desamparado e sem esperança.","orderIndex":1},{"id":"b150","title":"3. A Alegria do Senhor É a Vossa Força (Maoz)","biblicalReference":"Neemias 8:10b","explanation":"Maoz: fortaleza, baluarte, armadura protetora. A alegria não vem do riso oco do mundo, mas da certeza de que somos amados e perdoados pelo Senhor.","illustration":"O combustível de alta octanagem que faz o motor de um avião decolar suavemente acima das nuvens tempestuosas.","application":"Sorria no Senhor e celebre a vitória: a alegria que Ele coloca no seu peito é o seu maior escudo contra o cansaço.","orderIndex":2}],"conclusion":"Tristeza e desânimo enfraquecem o crente; a alegria do Senhor é a fortaleza que nos faz vencer todas as batalhas.","appeal":"Troque as vestes de luto pelas vestes de louvor e receba a alegria do Senhor nesta noite."}'::jsonb
  )
) AS v(title, theme, key_verse, sermon_type, tags, content)
WHERE NOT EXISTS (
  SELECT 1 FROM public.sermon_templates st WHERE st.title = v.title
);
